static const char* swoole_library_source_core_array_object =
    "\n"
    "/**\n"
    " * This file is part of Swoole.\n"
    " *\n"
    " * @link     https://www.swoole.com\n"
    " * @contact  team@swoole.com\n"
    " * @license  https://github.com/swoole/library/blob/master/LICENSE\n"
    " */\n"
    "\n"
    "declare(strict_types=1);\n"
    "\n"
    "namespace Swoole;\n"
    "\n"
    "use Swoole\\Exception\\ArrayKeyNotExists;\n"
    "\n"
    "// Serializable remains necessary to read legacy C-format payloads; new payloads use __serialize().\n"
    "class ArrayObject implements \\ArrayAccess, \\Serializable, \\Countable, \\Iterator\n"
    "{\n"
    "    /**\n"
    "     * @var array\n"
    "     */\n"
    "    protected $array;\n"
    "\n"
    "    /**\n"
    "     * ArrayObject constructor.\n"
    "     */\n"
    "    public function __construct(array $array = [])\n"
    "    {\n"
    "        $this->array = $array;\n"
    "    }\n"
    "\n"
    "    public function __toArray(): array\n"
    "    {\n"
    "        return $this->array;\n"
    "    }\n"
    "\n"
    "    public function __serialize(): array\n"
    "    {\n"
    "        return $this->array;\n"
    "    }\n"
    "\n"
    "    public function __unserialize(array $data): void\n"
    "    {\n"
    "        $this->array = $data;\n"
    "    }\n"
    "\n"
    "    public static function from(array $array = []): static\n"
    "    {\n"
    "        return new static($array); // @phpstan-ignore new.static\n"
    "    }\n"
    "\n"
    "    public function toArray(): array\n"
    "    {\n"
    "        return $this->array;\n"
    "    }\n"
    "\n"
    "    public function isEmpty(): bool\n"
    "    {\n"
    "        return empty($this->array);\n"
    "    }\n"
    "\n"
    "    public function count(): int\n"
    "    {\n"
    "        return count($this->array);\n"
    "    }\n"
    "\n"
    "    public function current(): mixed\n"
    "    {\n"
    "        return current($this->array);\n"
    "    }\n"
    "\n"
    "    public function key(): int|string|null\n"
    "    {\n"
    "        return key($this->array);\n"
    "    }\n"
    "\n"
    "    public function valid(): bool\n"
    "    {\n"
    "        return $this->key() !== null;\n"
    "    }\n"
    "\n"
    "    public function rewind(): void\n"
    "    {\n"
    "        reset($this->array);\n"
    "    }\n"
    "\n"
    "    public function next(): void\n"
    "    {\n"
    "        next($this->array);\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return mixed the value at the given key, with a string or an array wrapped in a StringObject or an ArrayObject\n"
    "     */\n"
    "    public function get(mixed $key)\n"
    "    {\n"
    "        // A null key is the empty string for PHP, which deprecates passing it as null as of PHP 8.5.\n"
    "        $key = $key ?? '';\n"
    "        if (!$this->exists($key)) {\n"
    "            throw new ArrayKeyNotExists((string) $key);\n"
    "        }\n"
    "        return static::detectType($this->array[$key]);\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return mixed the value at the given key (with a string or an array wrapped in a StringObject or an\n"
    "     *               ArrayObject), or the default value if the key does not exist\n"
    "     */\n"
    "    public function getOr(mixed $key, mixed $default = null)\n"
    "    {\n"
    "        $key = $key ?? '';\n"
    "        if (!$this->exists($key)) {\n"
    "            return $default;\n"
    "        }\n"
    "        return static::detectType($this->array[$key]);\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return mixed\n"
    "     */\n"
    "    public function last()\n"
    "    {\n"
    "        $key = array_key_last($this->array);\n"
    "        if ($key === null) {\n"
    "            return null;\n"
    "        }\n"
    "        return $this->get($key);\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return int|string|null\n"
    "     */\n"
    "    public function firstKey()\n"
    "    {\n"
    "        return array_key_first($this->array);\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return int|string|null\n"
    "     */\n"
    "    public function lastKey()\n"
    "    {\n"
    "        return array_key_last($this->array);\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return mixed\n"
    "     */\n"
    "    public function first()\n"
    "    {\n"
    "        $key = array_key_first($this->array);\n"
    "        if ($key === null) {\n"
    "            return null;\n"
    "        }\n"
    "        return $this->get($key);\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return $this\n"
    "     */\n"
    "    public function set(mixed $key, mixed $value): self\n"
    "    {\n"
    "        $key = $key ?? '';\n"
    "\n"
    "        $this->array[$key] = $value;\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return $this\n"
    "     */\n"
    "    public function delete(mixed $key): self\n"
    "    {\n"
    "        unset($this->array[$key]);\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return $this\n"
    "     */\n"
    "    public function remove(mixed $value, bool $strict = true, bool $loop = false): self\n"
    "    {\n"
    "        if (!$loop) {\n"
    "            $key = $this->search($value, $strict);\n"
    "            if ($key !== false) {\n"
    "                unset($this->array[$key]);\n"
    "            }\n"
    "            return $this;\n"
    "        }\n"
    "        // All the matching keys in one pass, instead of an array_search() from the start for every removal.\n"
    "        foreach (array_keys($this->array, $value, $strict) as $key) {\n"
    "            unset($this->array[$key]);\n"
    "        }\n"
    "\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return $this\n"
    "     */\n"
    "    public function clear(): self\n"
    "    {\n"
    "        $this->array = [];\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Array access returns the raw value, like a native array; get() provides wrapped values.\n"
    "     */\n"
    "    public function offsetGet(mixed $key): mixed\n"
    "    {\n"
    "        $key = $key ?? '';\n"
    "        if (!array_key_exists($key, $this->array)) {\n"
    "            return null;\n"
    "        }\n"
    "        return $this->array[$key];\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * A null key appends the value: it is what PHP passes for `$array[] = $value`, which it does not tell from\n"
    "     * `$array[null] = $value`. To write to the empty-string key, pass '' or use set().\n"
    "     */\n"
    "    public function offsetSet(mixed $key, mixed $value): void\n"
    "    {\n"
    "        if ($key === null) {\n"
    "            $this->array[] = $value;\n"
    "            return;\n"
    "        }\n"
    "\n"
    "        $this->array[$key] = $value;\n"
    "    }\n"
    "\n"
    "    public function offsetUnset(mixed $key): void\n"
    "    {\n"
    "        unset($this->array[$key]);\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Match isset() on a native array. Use exists() to include keys whose value is null.\n"
    "     */\n"
    "    public function offsetExists(mixed $key): bool\n"
    "    {\n"
    "        $key = $key ?? '';\n"
    "        return isset($this->array[$key]);\n"
    "    }\n"
    "\n"
    "    public function exists(mixed $key): bool\n"
    "    {\n"
    "        $key = $key ?? '';\n"
    "        return array_key_exists($key, $this->array);\n"
    "    }\n"
    "\n"
    "    public function contains(mixed $value, bool $strict = true): bool\n"
    "    {\n"
    "        return in_array($value, $this->array, $strict);\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return int|string|false the key of the first matching element, or false if the value is not found\n"
    "     */\n"
    "    public function indexOf(mixed $value, bool $strict = true)\n"
    "    {\n"
    "        return $this->search($value, $strict);\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return int|string|null the key of the last matching element, or null (unlike indexOf()) if the value is not\n"
    "     *                         found\n"
    "     */\n"
    "    public function lastIndexOf(mixed $value, bool $strict = true)\n"
    "    {\n"
    "        // array_keys() compares the way array_search() does (== or ===), without the copy of the array that\n"
    "        // walking it backwards with end()/prev() forced.\n"
    "        $keys = array_keys($this->array, $value, $strict);\n"
    "        return $keys ? $keys[array_key_last($keys)] : null;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return int|string|false the key of the first matching element, or false if the value is not found\n"
    "     */\n"
    "    public function search(mixed $needle, bool $strict = true)\n"
    "    {\n"
    "        return array_search($needle, $this->array, $strict);\n"
    "    }\n"
    "\n"
    "    public function join(string $glue = ''): StringObject\n"
    "    {\n"
    "        return self::detectStringType(implode($glue, $this->array));\n"
    "    }\n"
    "\n"
    "    public function serialize(): string\n"
    "    {\n"
    "        return serialize($this->array);\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Only allow object classes explicitly when restoring trusted data.\n"
    "     *\n"
    "     * @param bool|list<class-string> $allowed_classes\n"
    "     */\n"
    "    public function unserialize(string|\\Stringable|StringObject $string, bool|array $allowed_classes = false): self\n"
    "    {\n"
    "        $this->array = (array) unserialize((string) $string, ['allowed_classes' => $allowed_classes]);\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return float|int\n"
    "     */\n"
    "    public function sum()\n"
    "    {\n"
    "        return array_sum($this->array);\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return float|int\n"
    "     */\n"
    "    public function product()\n"
    "    {\n"
    "        return array_product($this->array);\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return int\n"
    "     */\n"
    "    public function push(mixed $value)\n"
    "    {\n"
    "        return $this->pushBack($value);\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return int\n"
    "     */\n"
    "    public function pushFront(mixed $value)\n"
    "    {\n"
    "        return array_unshift($this->array, $value);\n"
    "    }\n"
    "\n"
    "    public function append(mixed ...$values): ArrayObject\n"
    "    {\n"
    "        array_push($this->array, ...$values);\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return int\n"
    "     */\n"
    "    public function pushBack(mixed $value)\n"
    "    {\n"
    "        return array_push($this->array, $value);\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return $this\n"
    "     */\n"
    "    public function insert(int $offset, mixed $value): self\n"
    "    {\n"
    "        if (is_array($value) || is_object($value) || is_null($value)) {\n"
    "            $value = [$value];\n"
    "        }\n"
    "        array_splice($this->array, $offset, 0, $value);\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return mixed\n"
    "     */\n"
    "    public function pop()\n"
    "    {\n"
    "        return $this->popBack();\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return mixed\n"
    "     */\n"
    "    public function popFront()\n"
    "    {\n"
    "        return array_shift($this->array);\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return mixed\n"
    "     */\n"
    "    public function popBack()\n"
    "    {\n"
    "        return array_pop($this->array);\n"
    "    }\n"
    "\n"
    "    public function slice(int $offset, ?int $length = null, bool $preserve_keys = false): static\n"
    "    {\n"
    "        return new static(array_slice($this->array, $offset, $length, $preserve_keys)); // @phpstan-ignore new.static\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return mixed a randomly picked value, with a string or an array wrapped in a StringObject or an ArrayObject\n"
    "     */\n"
    "    public function randomGet()\n"
    "    {\n"
    "        if ($this->isEmpty()) {\n"
    "            return null;\n"
    "        }\n"
    "        return static::detectType($this->array[array_rand($this->array, 1)]);\n"
    "    }\n"
    "\n"
    "    public function each(callable $fn): self\n"
    "    {\n"
    "        array_walk($this->array, $fn);\n"
    "\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    public function map(callable $fn, array ...$args): static\n"
    "    {\n"
    "        return new static(array_map($fn, $this->array, ...$args)); // @phpstan-ignore new.static\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return mixed\n"
    "     */\n"
    "    public function reduce(callable $fn, mixed $initial = null)\n"
    "    {\n"
    "        return array_reduce($this->array, $fn, $initial);\n"
    "    }\n"
    "\n"
    "    public function keys(mixed ...$args): static\n"
    "    {\n"
    "        return new static(array_keys($this->array, ...$args)); // @phpstan-ignore new.static\n"
    "    }\n"
    "\n"
    "    public function values(): static\n"
    "    {\n"
    "        return new static(array_values($this->array)); // @phpstan-ignore new.static\n"
    "    }\n"
    "\n"
    "    public function column(mixed $column_key, mixed $index = null): static\n"
    "    {\n"
    "        return new static(array_column($this->array, $column_key, $index)); // @phpstan-ignore new.static\n"
    "    }\n"
    "\n"
    "    public function unique(int $sort_flags = SORT_STRING): static\n"
    "    {\n"
    "        return new static(array_unique($this->array, $sort_flags)); // @phpstan-ignore new.static\n"
    "    }\n"
    "\n"
    "    public function reverse(bool $preserve_keys = false): static\n"
    "    {\n"
    "        return new static(array_reverse($this->array, $preserve_keys)); // @phpstan-ignore new.static\n"
    "    }\n"
    "\n"
    "    public function chunk(int $size, bool $preserve_keys = false): static\n"
    "    {\n"
    "        return new static(array_chunk($this->array, $size, $preserve_keys)); // @phpstan-ignore new.static\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Swap keys and values in an array.\n"
    "     */\n"
    "    public function flip(): static\n"
    "    {\n"
    "        return new static(array_flip($this->array)); // @phpstan-ignore new.static\n"
    "    }\n"
    "\n"
    "    public function filter(callable $fn, int $flag = 0): static\n"
    "    {\n"
    "        return new static(array_filter($this->array, $fn, $flag)); // @phpstan-ignore new.static\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * | Function name     | Sorts by | Maintains key association   | Order of sort               | Related functions |\n"
    "     * | :---------------- | :------- | :-------------------------- | :-------------------------- | :---------------- |\n"
    "     * | array_multisort() | value    | associative yes, numeric no | first array or sort options | array_walk()      |\n"
    "     * | asort()           | value    | yes                         | low to high                 | arsort()          |\n"
    "     * | arsort()          | value    | yes                         | high to low                 | asort()           |\n"
    "     * | krsort()          | key      | yes                         | high to low                 | ksort()           |\n"
    "     * | ksort()           | key      | yes                         | low to high                 | asort()           |\n"
    "     * | natcasesort()     | value    | yes                         | natural, case insensitive   | natsort()         |\n"
    "     * | natsort()         | value    | yes                         | natural                     | natcasesort()     |\n"
    "     * | rsort()           | value    | no                          | high to low                 | sort()            |\n"
    "     * | shuffle()         | value    | no                          | random                      | array_rand()      |\n"
    "     * | sort()            | value    | no                          | low to high                 | rsort()           |\n"
    "     * | uasort()          | value    | yes                         | user defined                | uksort()          |\n"
    "     * | uksort()          | key      | yes                         | user defined                | uasort()          |\n"
    "     * | usort()           | value    | no                          | user defined                | uasort()          |\n"
    "     */\n"
    "\n"
    "    /**\n"
    "     * @return $this\n"
    "     */\n"
    "    public function asort(int $sort_flags = SORT_REGULAR): self\n"
    "    {\n"
    "        asort($this->array, $sort_flags);\n"
    "\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    public function arsort(int $sort_flags = SORT_REGULAR): self\n"
    "    {\n"
    "        arsort($this->array, $sort_flags);\n"
    "\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    public function krsort(int $sort_flags = SORT_REGULAR): self\n"
    "    {\n"
    "        krsort($this->array, $sort_flags);\n"
    "\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    public function ksort(int $sort_flags = SORT_REGULAR): self\n"
    "    {\n"
    "        ksort($this->array, $sort_flags);\n"
    "\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return $this\n"
    "     */\n"
    "    public function natcasesort(): self\n"
    "    {\n"
    "        natcasesort($this->array);\n"
    "\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return $this\n"
    "     */\n"
    "    public function natsort(): self\n"
    "    {\n"
    "        natsort($this->array);\n"
    "\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return $this\n"
    "     */\n"
    "    public function rsort(int $sort_flags = SORT_REGULAR): self\n"
    "    {\n"
    "        rsort($this->array, $sort_flags);\n"
    "\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    public function shuffle(): self\n"
    "    {\n"
    "        shuffle($this->array);\n"
    "\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    public function sort(int $sort_flags = SORT_REGULAR): self\n"
    "    {\n"
    "        sort($this->array, $sort_flags);\n"
    "\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    public function uasort(callable $value_compare_func): self\n"
    "    {\n"
    "        uasort($this->array, $value_compare_func);\n"
    "\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    public function uksort(callable $value_compare_func): self\n"
    "    {\n"
    "        uksort($this->array, $value_compare_func);\n"
    "\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    public function usort(callable $value_compare_func): self\n"
    "    {\n"
    "        usort($this->array, $value_compare_func);\n"
    "\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return mixed the value as is, with a string or an array wrapped in a StringObject or an ArrayObject\n"
    "     */\n"
    "    protected static function detectType(mixed $value)\n"
    "    {\n"
    "        if (is_string($value)) {\n"
    "            return static::detectStringType($value);\n"
    "        }\n"
    "        if (is_array($value)) {\n"
    "            return static::detectArrayType($value);\n"
    "        }\n"
    "        return $value;\n"
    "    }\n"
    "\n"
    "    protected static function detectStringType(string $value): StringObject\n"
    "    {\n"
    "        return new StringObject($value);\n"
    "    }\n"
    "\n"
    "    protected static function detectArrayType(array $value): static\n"
    "    {\n"
    "        return new static($value); // @phpstan-ignore new.static\n"
    "    }\n"
    "}\n";

static const char* swoole_library_source_core_object_proxy =
    "\n"
    "/**\n"
    " * This file is part of Swoole.\n"
    " *\n"
    " * @link     https://www.swoole.com\n"
    " * @contact  team@swoole.com\n"
    " * @license  https://github.com/swoole/library/blob/master/LICENSE\n"
    " */\n"
    "\n"
    "declare(strict_types=1);\n"
    "\n"
    "namespace Swoole;\n"
    "\n"
    "class ObjectProxy\n"
    "{\n"
    "    /** @var object */\n"
    "    protected $__object;\n"
    "\n"
    "    public function __construct(object $object)\n"
    "    {\n"
    "        $this->__object = $object;\n"
    "    }\n"
    "\n"
    "    public function __getObject()\n"
    "    {\n"
    "        return $this->__object;\n"
    "    }\n"
    "\n"
    "    public function __get(string $name)\n"
    "    {\n"
    "        return $this->__object->{$name};\n"
    "    }\n"
    "\n"
    "    public function __set(string $name, mixed $value): void\n"
    "    {\n"
    "        $this->__object->{$name} = $value;\n"
    "    }\n"
    "\n"
    "    public function __isset(string $name)\n"
    "    {\n"
    "        return isset($this->__object->{$name});\n"
    "    }\n"
    "\n"
    "    public function __unset(string $name): void\n"
    "    {\n"
    "        unset($this->__object->{$name});\n"
    "    }\n"
    "\n"
    "    public function __call(string $name, array $arguments)\n"
    "    {\n"
    "        return $this->__object->{$name}(...$arguments);\n"
    "    }\n"
    "\n"
    "    public function __invoke(mixed ...$arguments)\n"
    "    {\n"
    "        /** @var mixed $object */\n"
    "        $object = $this->__object;\n"
    "        return $object(...$arguments);\n"
    "    }\n"
    "}\n";

static const char* swoole_library_source_core_coroutine_wait_group =
    "\n"
    "/**\n"
    " * This file is part of Swoole.\n"
    " *\n"
    " * @link     https://www.swoole.com\n"
    " * @contact  team@swoole.com\n"
    " * @license  https://github.com/swoole/library/blob/master/LICENSE\n"
    " */\n"
    "\n"
    "declare(strict_types=1);\n"
    "\n"
    "namespace Swoole\\Coroutine;\n"
    "\n"
    "class WaitGroup\n"
    "{\n"
    "    protected Channel $chan;\n"
    "\n"
    "    protected int $count = 0;\n"
    "\n"
    "    protected bool $waiting = false;\n"
    "\n"
    "    public function __construct(int $delta = 0)\n"
    "    {\n"
    "        $this->chan = new Channel(1);\n"
    "        $this->add($delta);\n"
    "    }\n"
    "\n"
    "    public function add(int $delta = 1): void\n"
    "    {\n"
    "        if ($this->waiting) {\n"
    "            throw new \\BadMethodCallException('WaitGroup misuse: add called concurrently with wait');\n"
    "        }\n"
    "        $count = $this->count + $delta;\n"
    "        if ($count < 0) {\n"
    "            throw new \\InvalidArgumentException('WaitGroup misuse: negative counter');\n"
    "        }\n"
    "        $this->count = $count;\n"
    "    }\n"
    "\n"
    "    public function done(): void\n"
    "    {\n"
    "        $count = $this->count - 1;\n"
    "        if ($count < 0) {\n"
    "            throw new \\BadMethodCallException('WaitGroup misuse: negative counter');\n"
    "        }\n"
    "        $this->count = $count;\n"
    "        if ($count === 0 && $this->waiting) {\n"
    "            $this->chan->push(true);\n"
    "        }\n"
    "    }\n"
    "\n"
    "    public function wait(float $timeout = -1): bool\n"
    "    {\n"
    "        if ($this->waiting) {\n"
    "            throw new \\BadMethodCallException('WaitGroup misuse: reused before previous wait has returned');\n"
    "        }\n"
    "        if ($this->count > 0) {\n"
    "            $this->waiting = true;\n"
    "            try {\n"
    "                return $this->chan->pop($timeout);\n"
    "            } finally {\n"
    "                $this->waiting = false;\n"
    "            }\n"
    "        }\n"
    "        return true;\n"
    "    }\n"
    "\n"
    "    public function count(): int\n"
    "    {\n"
    "        return $this->count;\n"
    "    }\n"
    "}\n";

static const char* swoole_library_source_core_coroutine_server =
    "\n"
    "/**\n"
    " * This file is part of Swoole.\n"
    " *\n"
    " * @link     https://www.swoole.com\n"
    " * @contact  team@swoole.com\n"
    " * @license  https://github.com/swoole/library/blob/master/LICENSE\n"
    " */\n"
    "\n"
    "declare(strict_types=1);\n"
    "\n"
    "namespace Swoole\\Coroutine;\n"
    "\n"
    "use Swoole\\Constant;\n"
    "use Swoole\\Coroutine;\n"
    "use Swoole\\Coroutine\\Server\\Connection;\n"
    "use Swoole\\Exception;\n"
    "\n"
    "class Server\n"
    "{\n"
    "    /**\n"
    "     * Accept errors that concern one incoming connection rather than the listening socket: a connection the peer\n"
    "     * aborted during the handshake, and the network errors pending on a connection, which Linux reports through\n"
    "     * accept(2). The server keeps accepting after them. They are given by name, as not every platform has all\n"
    "     * of them.\n"
    "     */\n"
    "    private const TRANSIENT_ACCEPT_ERRORS = [\n"
    "        'SOCKET_ECONNABORTED',\n"
    "        'SOCKET_ENETDOWN',\n"
    "        'SOCKET_EPROTO',\n"
    "        'SOCKET_ENOPROTOOPT',\n"
    "        'SOCKET_EHOSTDOWN',\n"
    "        'SOCKET_ENONET',\n"
    "        'SOCKET_EHOSTUNREACH',\n"
    "        'SOCKET_EOPNOTSUPP',\n"
    "        'SOCKET_ENETUNREACH',\n"
    "    ];\n"
    "\n"
    "    /**\n"
    "     * The number of accept errors in a row the server skips at once. From then on it waits a moment before it\n"
    "     * accepts again, so that an error that does not go away cannot keep the other coroutines from running, and it\n"
    "     * raises a warning, once for each run of errors, so that the error does not go unnoticed.\n"
    "     */\n"
    "    private const TRANSIENT_ACCEPT_ERRORS_IN_A_ROW = 16;\n"
    "\n"
    "    /** @var string */\n"
    "    public $host = '';\n"
    "\n"
    "    /** @var int */\n"
    "    public $port = 0;\n"
    "\n"
    "    /** @var int */\n"
    "    public $type = AF_INET;\n"
    "\n"
    "    /** @var int */\n"
    "    public $fd = -1;\n"
    "\n"
    "    /** @var int */\n"
    "    public $errCode = 0;\n"
    "\n"
    "    /** @var array */\n"
    "    public $setting = [];\n"
    "\n"
    "    /** @var bool */\n"
    "    protected $running = false;\n"
    "\n"
    "    /** @var callable|null */\n"
    "    protected $fn;\n"
    "\n"
    "    /** @var Socket */\n"
    "    protected $socket;\n"
    "\n"
    "    private bool $stopped = false;\n"
    "\n"
    "    /**\n"
    "     * Server constructor.\n"
    "     * @throws Exception\n"
    "     */\n"
    "    public function __construct(string $host, int $port = 0, bool $ssl = false, bool $reuse_port = false)\n"
    "    {\n"
    "        $_host = swoole_string($host);\n"
    "        if ($_host->contains('::')) {\n"
    "            $this->type = AF_INET6;\n"
    "        } elseif ($_host->startsWith('unix:/')) {\n"
    "            $host       = $_host->substr(5)->__toString();\n"
    "            $this->type = AF_UNIX;\n"
    "        } else {\n"
    "            $this->type = AF_INET;\n"
    "        }\n"
    "        $this->host = $host;\n"
    "\n"
    "        $socket = new Socket($this->type, SOCK_STREAM, 0);\n"
    "        if ($reuse_port && defined('SO_REUSEPORT')) {\n"
    "            $socket->setOption(SOL_SOCKET, SO_REUSEPORT, true);\n"
    "        }\n"
    "        if (!$socket->bind($this->host, $port)) {\n"
    "            throw new Exception(\"bind({$this->host}:{$port}) failed\", $socket->errCode);\n"
    "        }\n"
    "        if (!$socket->listen()) {\n"
    "            throw new Exception('listen() failed', $socket->errCode);\n"
    "        }\n"
    "        $this->port                = $socket->getsockname()['port'] ?? 0;\n"
    "        $this->fd                  = $socket->fd;\n"
    "        $this->socket              = $socket;\n"
    "        $this->setting['open_ssl'] = $ssl;\n"
    "    }\n"
    "\n"
    "    public function set(array $setting): void\n"
    "    {\n"
    "        $this->setting = array_merge($this->setting, $setting);\n"
    "    }\n"
    "\n"
    "    public function handle(callable $fn): void\n"
    "    {\n"
    "        $this->fn = $fn;\n"
    "    }\n"
    "\n"
    "    public function shutdown(): bool\n"
    "    {\n"
    "        $this->running = false;\n"
    "        $this->stopped = true;\n"
    "        return $this->socket->cancel();\n"
    "    }\n"
    "\n"
    "    public function start(): bool\n"
    "    {\n"
    "        if ($this->running || $this->stopped) {\n"
    "            $this->errCode = $this->running ? SOCKET_EALREADY : SOCKET_EINVAL;\n"
    "            return false;\n"
    "        }\n"
    "        if ($this->fn === null) {\n"
    "            $this->errCode = SOCKET_EINVAL;\n"
    "            return false;\n"
    "        }\n"
    "        $socket = $this->socket;\n"
    "        if (!$socket->setProtocol($this->setting)) {\n"
    "            $this->errCode = SOCKET_EINVAL;\n"
    "            return false;\n"
    "        }\n"
    "\n"
    "        $this->running = true;\n"
    "        try {\n"
    "            $skipped = 0;\n"
    "            while ($this->running) {\n"
    "                $conn = $socket->accept();\n"
    "                if ($conn) {\n"
    "                    $skipped = 0;\n"
    "                    $conn->setProtocol($this->setting);\n"
    "                    if (!empty($this->setting[Constant::OPTION_OPEN_SSL])) {\n"
    "                        $fn = static function ($fn, $connection) {\n"
    "                            /* @var $connection Connection */\n"
    "                            if (!$connection->exportSocket()->sslHandshake()) {\n"
    "                                return;\n"
    "                            }\n"
    "                            $fn($connection);\n"
    "                        };\n"
    "                        $arguments = [$this->fn, new Connection($conn)];\n"
    "                    } else {\n"
    "                        $fn        = $this->fn;\n"
    "                        $arguments = [new Connection($conn)];\n"
    "                    }\n"
    "                    if (Coroutine::create($fn, ...$arguments) === false) {\n"
    "                        goto _wait;\n"
    "                    }\n"
    "                } else {\n"
    "                    if ($socket->errCode == SOCKET_EMFILE || $socket->errCode == SOCKET_ENFILE) {\n"
    "                        _wait:\n"
    "                        Coroutine::sleep(1);\n"
    "                        continue;\n"
    "                    }\n"
    "                    if ($socket->errCode == SOCKET_ETIMEDOUT) {\n"
    "                        continue;\n"
    "                    }\n"
    "                    if (self::isTransientAcceptError($socket->errCode)) {\n"
    "                        if (++$skipped > self::TRANSIENT_ACCEPT_ERRORS_IN_A_ROW) {\n"
    "                            if ($skipped === self::TRANSIENT_ACCEPT_ERRORS_IN_A_ROW + 1) {\n"
    "                                try {\n"
    "                                    trigger_error(\"accept keeps failing, Error: {$socket->errMsg}[{$socket->errCode}]; the server goes on accepting, a millisecond apart\", E_USER_WARNING);\n"
    "                                } catch (\\Throwable) {\n"
    "                                    // An error handler that turns warnings into exceptions must not stop the server: the\n"
    "                                    // warning only reports that it goes on.\n"
    "                                }\n"
    "                            }\n"
    "                            Coroutine::sleep(0.001);\n"
    "                        }\n"
    "                        continue;\n"
    "                    }\n"
    "                    if ($socket->errCode == SOCKET_ECANCELED) {\n"
    "                        break;\n"
    "                    }\n"
    "                    $this->errCode = $socket->errCode;\n"
    "                    trigger_error(\"accept failed, Error: {$socket->errMsg}[{$socket->errCode}]\", E_USER_WARNING);\n"
    "                    return false;\n"
    "                }\n"
    "            }\n"
    "\n"
    "            return true;\n"
    "        } finally {\n"
    "            $this->running = false;\n"
    "            $this->stopped = true;\n"
    "        }\n"
    "    }\n"
    "\n"
    "    private static function isTransientAcceptError(int $errCode): bool\n"
    "    {\n"
    "        static $errors = null;\n"
    "\n"
    "        if ($errors === null) {\n"
    "            $errors = [];\n"
    "            foreach (self::TRANSIENT_ACCEPT_ERRORS as $name) {\n"
    "                if (defined($name)) {\n"
    "                    $errors[constant($name)] = true;\n"
    "                }\n"
    "            }\n"
    "        }\n"
    "\n"
    "        return isset($errors[$errCode]);\n"
    "    }\n"
    "}\n";

static const char* swoole_library_source_core_coroutine_server_connection =
    "\n"
    "/**\n"
    " * This file is part of Swoole.\n"
    " *\n"
    " * @link     https://www.swoole.com\n"
    " * @contact  team@swoole.com\n"
    " * @license  https://github.com/swoole/library/blob/master/LICENSE\n"
    " */\n"
    "\n"
    "declare(strict_types=1);\n"
    "\n"
    "namespace Swoole\\Coroutine\\Server;\n"
    "\n"
    "use Swoole\\Coroutine\\Socket;\n"
    "\n"
    "class Connection\n"
    "{\n"
    "    protected $socket;\n"
    "\n"
    "    public function __construct(Socket $conn)\n"
    "    {\n"
    "        $this->socket = $conn;\n"
    "    }\n"
    "\n"
    "    public function recv(float $timeout = 0)\n"
    "    {\n"
    "        return $this->socket->recvPacket($timeout);\n"
    "    }\n"
    "\n"
    "    public function send(string $data)\n"
    "    {\n"
    "        return $this->socket->sendAll($data);\n"
    "    }\n"
    "\n"
    "    public function close(): bool\n"
    "    {\n"
    "        return $this->socket->close();\n"
    "    }\n"
    "\n"
    "    public function exportSocket(): Socket\n"
    "    {\n"
    "        return $this->socket;\n"
    "    }\n"
    "}\n";

static const char* swoole_library_source_core_coroutine_barrier =
    "\n"
    "/**\n"
    " * This file is part of Swoole.\n"
    " *\n"
    " * @link     https://www.swoole.com\n"
    " * @contact  team@swoole.com\n"
    " * @license  https://github.com/swoole/library/blob/master/LICENSE\n"
    " */\n"
    "\n"
    "declare(strict_types=1);\n"
    "\n"
    "namespace Swoole\\Coroutine;\n"
    "\n"
    "use Swoole\\Coroutine;\n"
    "use Swoole\\Exception;\n"
    "use Swoole\\Timer;\n"
    "\n"
    "class Barrier\n"
    "{\n"
    "    private ?object $waitState = null;\n"
    "\n"
    "    public function __destruct()\n"
    "    {\n"
    "        $this->waitState?->release();\n"
    "    }\n"
    "\n"
    "    public static function make(): self\n"
    "    {\n"
    "        return new self();\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @param-out null $barrier\n"
    "     */\n"
    "    public static function wait(Barrier &$barrier, float $timeout = -1): void\n"
    "    {\n"
    "        if ($barrier->waitState !== null) {\n"
    "            throw new Exception('The barrier is waiting, cannot wait again.');\n"
    "        }\n"
    "        if (!is_finite($timeout)) {\n"
    "            throw new \\InvalidArgumentException('Barrier timeout must be finite');\n"
    "        }\n"
    "        // Keep the wait state separate: retaining the barrier itself here would prevent its destruction.\n"
    "        $state = $barrier->waitState = new class(Coroutine::getCid()) {\n"
    "            public ?int $timer = null;\n"
    "\n"
    "            private bool $waiting = false;\n"
    "\n"
    "            private bool $released = false;\n"
    "\n"
    "            private bool $finished = false;\n"
    "\n"
    "            public function __construct(private readonly int $cid)\n"
    "            {\n"
    "            }\n"
    "\n"
    "            public function release(): void\n"
    "            {\n"
    "                if ($this->finished) {\n"
    "                    return;\n"
    "                }\n"
    "                $this->released = true;\n"
    "                if ($this->waiting) {\n"
    "                    Coroutine::resume($this->cid);\n"
    "                }\n"
    "            }\n"
    "\n"
    "            public function wait(): void\n"
    "            {\n"
    "                if (!$this->released) {\n"
    "                    $this->waiting = true;\n"
    "                    Coroutine::yield();\n"
    "                }\n"
    "            }\n"
    "\n"
    "            public function finish(): void\n"
    "            {\n"
    "                $this->finished = true;\n"
    "                $this->waiting  = false;\n"
    "                if ($this->timer !== null && Timer::exists($this->timer)) {\n"
    "                    Timer::clear($this->timer);\n"
    "                }\n"
    "            }\n"
    "        };\n"
    "        try {\n"
    "            if ($timeout > 0) {\n"
    "                $state->timer = Timer::after(max(1, (int) ceil($timeout * 1000)), $state->release(...));\n"
    "            }\n"
    "            $barrier = null;\n"
    "            $state->wait();\n"
    "        } finally {\n"
    "            $state->finish();\n"
    "        }\n"
    "    }\n"
    "}\n";

static const char* swoole_library_source_core_coroutine_http_client_proxy =
    "\n"
    "/**\n"
    " * This file is part of Swoole.\n"
    " *\n"
    " * @link     https://www.swoole.com\n"
    " * @contact  team@swoole.com\n"
    " * @license  https://github.com/swoole/library/blob/master/LICENSE\n"
    " */\n"
    "\n"
    "declare(strict_types=1);\n"
    "\n"
    "namespace Swoole\\Coroutine\\Http;\n"
    "\n"
    "class ClientProxy\n"
    "{\n"
    "    private readonly array $headers;\n"
    "\n"
    "    private readonly array $cookies;\n"
    "\n"
    "    public function __construct(private readonly string $body, private readonly int $statusCode, ?array $headers, ?array $cookies)\n"
    "    {\n"
    "        $this->headers = $headers ?? [];\n"
    "        $this->cookies = $cookies ?? [];\n"
    "    }\n"
    "\n"
    "    public function getBody(): string\n"
    "    {\n"
    "        return $this->body;\n"
    "    }\n"
    "\n"
    "    public function getStatusCode(): int\n"
    "    {\n"
    "        return $this->statusCode;\n"
    "    }\n"
    "\n"
    "    public function getHeaders(): array\n"
    "    {\n"
    "        return $this->headers;\n"
    "    }\n"
    "\n"
    "    public function getCookies(): array\n"
    "    {\n"
    "        return $this->cookies;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Parse the final header block, discarding interim responses and redirects.\n"
    "     *\n"
    "     * @param list<string> $lines\n"
    "     */\n"
    "    public static function fromHeaders(string $body, array $lines, int $defaultStatus = 200): self\n"
    "    {\n"
    "        $status  = $defaultStatus;\n"
    "        $headers = $cookies = [];\n"
    "        foreach ($lines as $line) {\n"
    "            if (preg_match('/^HTTP\\/\\S+\\s+(\\d{3})/', $line, $matches)) {\n"
    "                $status  = (int) $matches[1];\n"
    "                $headers = $cookies = [];\n"
    "                continue;\n"
    "            }\n"
    "            $parts = explode(':', $line, 2);\n"
    "            if (count($parts) !== 2) {\n"
    "                continue;\n"
    "            }\n"
    "            $name             = strtolower(trim($parts[0]));\n"
    "            $value            = trim($parts[1]);\n"
    "            $headers[$name][] = $value;\n"
    "            if ($name === 'set-cookie') {\n"
    "                $cookie = explode('=', explode(';', $value, 2)[0], 2);\n"
    "                if (count($cookie) === 2 && trim($cookie[0]) !== '') {\n"
    "                    $cookies[trim($cookie[0])] = trim($cookie[1]);\n"
    "                }\n"
    "            }\n"
    "        }\n"
    "        return new self($body, $status, $headers, $cookies);\n"
    "    }\n"
    "}\n";

static const char* swoole_library_source_core_coroutine_http_functions =
    "\n"
    "/**\n"
    " * This file is part of Swoole.\n"
    " *\n"
    " * @link     https://www.swoole.com\n"
    " * @contact  team@swoole.com\n"
    " * @license  https://github.com/swoole/library/blob/master/LICENSE\n"
    " */\n"
    "\n"
    "declare(strict_types=1);\n"
    "\n"
    "namespace Swoole\\Coroutine\\Http;\n"
    "\n"
    "use Swoole\\Coroutine\\Http\\Client\\Exception;\n"
    "\n"
    "/**\n"
    " * @throws Exception\n"
    " */\n"
    "function request(\n"
    "    string $url,\n"
    "    string $method,\n"
    "    mixed $data = null,\n"
    "    ?array $options = null,\n"
    "    ?array $headers = null,\n"
    "    ?array $cookies = null,\n"
    "): ClientProxy {\n"
    "    $driver = swoole_library_get_option('http_client_driver');\n"
    "    return match ($driver) {\n"
    "        'curl'              => request_with_curl($url, $method, $data, $options, $headers, $cookies),\n"
    "        'stream'            => request_with_stream($url, $method, $data, $options, $headers, $cookies),\n"
    "        null, 'http_client' => request_with_http_client($url, $method, $data, $options, $headers, $cookies),\n"
    "        default             => throw new Exception('unknown HTTP client driver: ' . var_export($driver, true)),\n"
    "    };\n"
    "}\n"
    "\n"
    "/**\n"
    " * @throws Exception\n"
    " */\n"
    "function request_with_http_client(\n"
    "    string $url,\n"
    "    string $method,\n"
    "    mixed $data = null,\n"
    "    ?array $options = null,\n"
    "    ?array $headers = null,\n"
    "    ?array $cookies = null,\n"
    "): ClientProxy {\n"
    "    $info = parse_url($url);\n"
    "    if (empty($info['scheme'])) {\n"
    "        throw new Exception('The URL given is illegal [no scheme]');\n"
    "    }\n"
    "    if (empty($info['host'])) {\n"
    "        throw new Exception('The URL given is illegal [no host]');\n"
    "    }\n"
    "    if ($info['scheme'] == 'http') {\n"
    "        $client = new Client($info['host'], swoole_array_default_value($info, 'port', 80), false);\n"
    "    } elseif ($info['scheme'] == 'https') {\n"
    "        $client = new Client($info['host'], swoole_array_default_value($info, 'port', 443), true);\n"
    "    } else {\n"
    "        throw new Exception('unknown scheme \"' . $info['scheme'] . '\"');\n"
    "    }\n"
    "    $client->setMethod($method);\n"
    "    if ($data !== null) {\n"
    "        $client->setData(is_array($data) ? $data : (string) $data);\n"
    "    }\n"
    "    $client->set($options ?: []);\n"
    "    $client->setHeaders($headers ?: []);\n"
    "    $client->setCookies($cookies ?: []);\n"
    "    $request_url = swoole_array_default_value($info, 'path', '/');\n"
    "    if (isset($info['query']) && $info['query'] !== '') {\n"
    "        $request_url .= '?' . $info['query'];\n"
    "    }\n"
    "    if ($client->execute($request_url)) {\n"
    "        return new ClientProxy(\n"
    "            $client->getBody(),\n"
    "            $client->getStatusCode(),\n"
    "            $client->getHeaders() ?: [],\n"
    "            $client->getCookies() ?: []\n"
    "        );\n"
    "    }\n"
    "    throw new Exception($client->errMsg, $client->errCode);\n"
    "}\n"
    "\n"
    "/**\n"
    " * @throws Exception\n"
    " */\n"
    "function request_with_curl(\n"
    "    string $url,\n"
    "    string $method,\n"
    "    mixed $data = null,\n"
    "    ?array $options = null,\n"
    "    ?array $headers = null,\n"
    "    ?array $cookies = null,\n"
    "): ClientProxy {\n"
    "    $ch = curl_init($url);\n"
    "    if (empty($ch)) {\n"
    "        throw new Exception('failed to curl_init');\n"
    "    }\n"
    "    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);\n"
    "    curl_setopt($ch, CURLOPT_CUSTOMREQUEST, strtoupper($method));\n"
    "    $responseHeaderLines = [];\n"
    "    curl_setopt($ch, CURLOPT_HEADERFUNCTION, static function ($ch, string $header) use (&$responseHeaderLines): int {\n"
    "        $responseHeaderLines[] = $header;\n"
    "        return strlen($header);\n"
    "    });\n"
    "    if ($data !== null) {\n"
    "        curl_setopt($ch, CURLOPT_POSTFIELDS, is_array($data) ? $data : (string) $data);\n"
    "    }\n"
    "    if ($headers !== null) {\n"
    "        $headerLines = [];\n"
    "        foreach ($headers as $key => $value) {\n"
    "            $headerLines[] = is_int($key) ? $value : \"{$key}: {$value}\";\n"
    "        }\n"
    "        curl_setopt($ch, CURLOPT_HTTPHEADER, $headerLines);\n"
    "    }\n"
    "    if ($cookies !== null) {\n"
    "        $cookie_str = '';\n"
    "        foreach ($cookies as $k => $v) {\n"
    "            $cookie_str .= \"{$k}={$v}; \";\n"
    "        }\n"
    "        curl_setopt($ch, CURLOPT_COOKIE, $cookie_str);\n"
    "    }\n"
    "    if (isset($options['timeout'])) {\n"
    "        if (is_float($options['timeout'])) {\n"
    "            curl_setopt($ch, CURLOPT_TIMEOUT_MS, intval($options['timeout'] * 1000));\n"
    "            curl_setopt($ch, CURLOPT_CONNECTTIMEOUT_MS, intval($options['timeout'] * 1000));\n"
    "        } else {\n"
    "            curl_setopt($ch, CURLOPT_TIMEOUT, intval($options['timeout']));\n"
    "            curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, intval($options['timeout']));\n"
    "        }\n"
    "    }\n"
    "    if (isset($options['connect_timeout'])) {\n"
    "        if (is_float($options['connect_timeout'])) {\n"
    "            curl_setopt($ch, CURLOPT_CONNECTTIMEOUT_MS, intval($options['connect_timeout'] * 1000));\n"
    "        } else {\n"
    "            curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, intval($options['connect_timeout']));\n"
    "        }\n"
    "    }\n"
    "    $body = curl_exec($ch);\n"
    "    if ($body !== false) {\n"
    "        return ClientProxy::fromHeaders($body, $responseHeaderLines, curl_getinfo($ch, CURLINFO_RESPONSE_CODE));\n"
    "    }\n"
    "    throw new Exception(curl_error($ch), curl_errno($ch));\n"
    "}\n"
    "\n"
    "/**\n"
    " * @throws Exception\n"
    " */\n"
    "function request_with_stream(\n"
    "    string $url,\n"
    "    string $method,\n"
    "    mixed $data = null,\n"
    "    ?array $options = null,\n"
    "    ?array $headers = null,\n"
    "    ?array $cookies = null,\n"
    "): ClientProxy {\n"
    "    $stream_options = [\n"
    "        'http' => [\n"
    "            'method'        => $method,\n"
    "            'ignore_errors' => true,\n"
    "        ],\n"
    "    ];\n"
    "    $headerStr = '';\n"
    "    if ($headers !== null) {\n"
    "        foreach ($headers as $k => $v) {\n"
    "            $headerStr .= is_int($k) ? $v . \"\\r\\n\" : \"{$k}: {$v}\\r\\n\";\n"
    "        }\n"
    "    }\n"
    "    if ($cookies !== null && $cookies !== []) {\n"
    "        $cookieParts = [];\n"
    "        foreach ($cookies as $k => $v) {\n"
    "            $cookieParts[] = \"{$k}={$v}\";\n"
    "        }\n"
    "        $headerStr .= 'Cookie: ' . implode('; ', $cookieParts) . \"\\r\\n\";\n"
    "    }\n"
    "    if (isset($options['timeout'])) {\n"
    "        $stream_options['http']['timeout'] = (float) $options['timeout'];\n"
    "    }\n"
    "    if ($data !== null) {\n"
    "        if (is_array($data)) {\n"
    "            $headerStr .= \"Content-type: application/x-www-form-urlencoded\\r\\n\";\n"
    "            $stream_options['http']['content'] = http_build_query($data);\n"
    "        } else {\n"
    "            $stream_options['http']['content'] = strval($data);\n"
    "        }\n"
    "    }\n"
    "    if ($headerStr) {\n"
    "        $stream_options['http']['header'] = $headerStr;\n"
    "    }\n"
    "    $http_response_header = [];\n"
    "    $body                 = @file_get_contents($url, false, stream_context_create($stream_options));\n"
    "    if ($body !== false) {\n"
    "        return ClientProxy::fromHeaders($body, $http_response_header);\n"
    "    }\n"
    "    $error = error_get_last();\n"
    "    throw new Exception((string) ($error['message'] ?? 'failed to read HTTP response'));\n"
    "}\n"
    "\n"
    "/**\n"
    " * @throws Exception\n"
    " */\n"
    "function post(string $url, mixed $data, ?array $options = null, ?array $headers = null, ?array $cookies = null): ClientProxy\n"
    "{\n"
    "    return request($url, 'POST', $data, $options, $headers, $cookies);\n"
    "}\n"
    "\n"
    "/**\n"
    " * @throws Exception\n"
    " */\n"
    "function get(string $url, ?array $options = null, ?array $headers = null, ?array $cookies = null): ClientProxy\n"
    "{\n"
    "    return request($url, 'GET', null, $options, $headers, $cookies);\n"
    "}\n";

static const char* swoole_library_source_core_coroutine_http2_multiplex_client =
    "\n"
    "/**\n"
    " * This file is part of Swoole.\n"
    " *\n"
    " * @link     https://www.swoole.com\n"
    " * @contact  team@swoole.com\n"
    " * @license  https://github.com/swoole/library/blob/master/LICENSE\n"
    " */\n"
    "\n"
    "declare(strict_types=1);\n"
    "\n"
    "namespace Swoole\\Coroutine\\Http2;\n"
    "\n"
    "use Swoole\\Constant;\n"
    "use Swoole\\Coroutine\\Channel;\n"
    "use Swoole\\Http2\\Request;\n"
    "use Swoole\\Http2\\Response;\n"
    "\n"
    "use function Swoole\\Coroutine\\go;\n"
    "\n"
    "// This file is packed into the Swoole extension and evaluated at startup, where declaring a class\n"
    "// whose parent is missing is a fatal error; the parent class only exists when the extension is\n"
    "// compiled with HTTP/2 support (--enable-http2).\n"
    "if (!class_exists(Client::class, false)) {\n"
    "    return;\n"
    "}\n"
    "\n"
    "/**\n"
    " * An HTTP/2 client that multiplexes requests from many coroutines over one shared connection.\n"
    " * Available only with HTTP/2 support; check class_exists(Client::class, false) before using it.\n"
    " *\n"
    " * A single recv-loop coroutine reads every response off the connection and routes it to the\n"
    " * requesting coroutine by stream ID. The connection is established on demand and re-established\n"
    " * transparently after a teardown (the pre-send health check only verifies the local socket state,\n"
    " * not peer liveness); a heartbeat checker closes it after a period without requests.\n"
    " *\n"
    " * The connection is owned by that machinery: the frame-level API inherited from the base class\n"
    " * (send(), recv(), read(), write(), goaway()) is disabled and throws. Use request().\n"
    " * A connection with 128 unanswered abandoned streams is closed to bound retained state. Other\n"
    " * in-flight requests then fail as on any connection close; the next request reconnects.\n"
    " *\n"
    " * Besides the settings understood by the underlying client, set() accepts two options that borrow\n"
    " * Swoole\\Server's heartbeat vocabulary -- here they govern the client's own outbound connection:\n"
    " * - heartbeat_check_interval: seconds between two idle checks (default:\n"
    " *   DEFAULT_HEARTBEAT_CHECK_INTERVAL; non-positive values fall back to the default)\n"
    " * - heartbeat_idle_time: seconds without a new request after which a connection with no in-flight\n"
    " *   requests is closed automatically (default: DEFAULT_HEARTBEAT_IDLE_TIME); a non-positive value\n"
    " *   disables idle closing, in which case the connection stays open until close() is called or the\n"
    " *   peer closes it\n"
    " * Both are read when the heartbeat checker starts; changing them on a client whose checker is\n"
    " * already running takes effect only after the next close().\n"
    " *\n"
    " * Call close() once the client is no longer needed. The recv loop and the heartbeat checker are\n"
    " * coroutines of their own, and Swoole\\Coroutine\\run() returns only after every coroutine has ended:\n"
    " * a client left open holds it back until the connection is closed for being idle, which takes up to\n"
    " * heartbeat_idle_time plus heartbeat_check_interval seconds, and for as long as the peer keeps the\n"
    " * connection open when idle closing is disabled.\n"
    " */\n"
    "final class MultiplexClient extends Client\n"
    "{\n"
    "    private const DEFAULT_HEARTBEAT_CHECK_INTERVAL = 3;\n"
    "\n"
    "    private const DEFAULT_HEARTBEAT_IDLE_TIME = 10;\n"
    "\n"
    "    // Recycle the connection if the peer never answers abandoned streams, bounding their tombstones.\n"
    "    private const MAX_ABANDONED_STREAMS = 128;\n"
    "\n"
    "    /**\n"
    "     * @var object|null identity token of the currently running recv loop; null when none is running.\n"
    "     *                  A recv loop whose token no longer matches is stale and must exit without\n"
    "     *                  closing the client: a newer loop may own the (reconnected) connection already.\n"
    "     */\n"
    "    private ?object $recvLoopToken = null;\n"
    "\n"
    "    /**\n"
    "     * @var Channel|null used by the heartbeat checker for an interruptible sleep; closed by close()\n"
    "     *                   to wake the checker up immediately\n"
    "     */\n"
    "    private ?Channel $sleepChannel = null;\n"
    "\n"
    "    /**\n"
    "     * @var Channel|null present while a coroutine health-checks the connection and starts the shared\n"
    "     *                   recv loop; other coroutines block on it (until it is closed) before sending\n"
    "     */\n"
    "    private ?Channel $startupBarrier = null;\n"
    "\n"
    "    /**\n"
    "     * @var array<int, Channel> per-stream channels carrying the responses of in-flight requests\n"
    "     */\n"
    "    private array $streamChannels = [];\n"
    "\n"
    "    /**\n"
    "     * @var array<int, true> IDs of streams whose requester timed out; the recv loop drops their late\n"
    "     *                       responses instead of parking them\n"
    "     */\n"
    "    private array $abandonedStreams = [];\n"
    "\n"
    "    /**\n"
    "     * @var bool guards against spawning more than one heartbeat-checker coroutine\n"
    "     */\n"
    "    private bool $heartbeatCheckerRunning = false;\n"
    "\n"
    "    /**\n"
    "     * @var int number of request() calls currently in progress -- including connection setup and\n"
    "     *          sending, where no stream channel exists yet; the heartbeat checker must not close\n"
    "     *          the connection while one is pending\n"
    "     */\n"
    "    private int $pendingRequests = 0;\n"
    "\n"
    "    /**\n"
    "     * @var float Unix timestamp of the completion of the most recent request() call, successful or\n"
    "     *            not; the heartbeat checker measures idleness against it\n"
    "     */\n"
    "    private float $lastActiveTime = 0;\n"
    "\n"
    "    /**\n"
    "     * Sends a request over the shared connection and waits for its response.\n"
    "     *\n"
    "     * Safe to call from any number of coroutines concurrently; the connection is established (or\n"
    "     * re-established) on demand.\n"
    "     *\n"
    "     * @param float $timeout seconds to wait for the response. Non-positive values fall back to the\n"
    "     *                       client's `timeout` setting; without that setting the wait is unbounded.\n"
    "     * @return false|Response the response, or false on failure: the connection could not be\n"
    "     *                        established, sending failed, the wait timed out or was canceled, or\n"
    "     *                        the connection was closed while waiting. errCode/errMsg describe the\n"
    "     *                        cause -- best-effort only: they live on the shared client, so read\n"
    "     *                        them immediately after the false return, before yielding; a\n"
    "     *                        concurrently failing request may overwrite them.\n"
    "     */\n"
    "    public function request(Request $request, float $timeout = -1): false|Response\n"
    "    {\n"
    "        if ($timeout <= 0) {\n"
    "            // The ping check in ensureRecvLoop() only confirms the request could be written out, not\n"
    "            // that the peer is alive, so an unbounded default wait could hang on a stale connection\n"
    "            // forever.\n"
    "            $timeout = (float) ($this->setting[Constant::OPTION_TIMEOUT] ?? -1);\n"
    "        }\n"
    "        // The counter -- not the stream-channel registry, which only has an entry once send() has\n"
    "        // returned -- is what keeps the heartbeat checker from closing the connection while a\n"
    "        // request is still connecting, sending, or waiting.\n"
    "        $this->pendingRequests++;\n"
    "        try {\n"
    "            if (!$this->ensureRecvLoop()) {\n"
    "                return false;\n"
    "            }\n"
    "            $streamId = parent::send($request);\n"
    "            if ($streamId === false) {\n"
    "                return false;\n"
    "            }\n"
    "            // The response can arrive before send() returns when send() yields on socket I/O; the\n"
    "            // recv loop then has registered the stream channel already, with the response buffered\n"
    "            // in it.\n"
    "            $chan = $this->streamChannels[$streamId] ?? null;\n"
    "            if ($chan === null) {\n"
    "                if ($this->recvLoopToken === null) {\n"
    "                    // The client was closed while send() yielded, and the flush has already dropped\n"
    "                    // any response parked for this stream: fail fast instead of waiting out the\n"
    "                    // timeout on a channel nothing will ever push to.\n"
    "                    $this->setError(SWOOLE_ERROR_CLIENT_NO_CONNECTION, 'the connection was closed while the request was being sent');\n"
    "                    return false;\n"
    "                }\n"
    "                $chan = $this->openStreamChannel($streamId);\n"
    "            }\n"
    "            $data = false;\n"
    "            try {\n"
    "                $data = $chan->pop($timeout);\n"
    "            } finally {\n"
    "                $this->closeStreamChannel($streamId);\n"
    "                if ($data === false) {\n"
    "                    if ($chan->errCode === SWOOLE_CHANNEL_CLOSED) {\n"
    "                        // Connection teardown: no abandoned-stream marker may be left behind --\n"
    "                        // stream IDs restart after a reconnect, and a stale marker would drop a\n"
    "                        // response of the next connection.\n"
    "                        $this->setError(SWOOLE_ERROR_CLIENT_NO_CONNECTION, 'the connection was closed while waiting for the response');\n"
    "                    } else {\n"
    "                        // Timed out or canceled: nobody waits for this stream anymore, but the\n"
    "                        // connection lives on -- the recv loop must drop the late response instead\n"
    "                        // of parking it, which would leak the parked channel (and block idle\n"
    "                        // closing) until the connection closes.\n"
    "                        $this->abandonedStreams[$streamId] = true;\n"
    "                        if ($chan->errCode === SWOOLE_CHANNEL_TIMEOUT) {\n"
    "                            $this->setError(SWOOLE_ERROR_CO_TIMEDOUT, 'the response timed out');\n"
    "                        } else {\n"
    "                            $this->setError(SWOOLE_ERROR_CO_CANCELED, 'the wait for the response was canceled');\n"
    "                        }\n"
    "                        if (count($this->abandonedStreams) >= self::MAX_ABANDONED_STREAMS) {\n"
    "                            // close() also wakes other in-flight requests; their callers can retry on a fresh connection.\n"
    "                            $this->close();\n"
    "                        }\n"
    "                    }\n"
    "                }\n"
    "            }\n"
    "\n"
    "            return $data;\n"
    "        } finally {\n"
    "            $this->pendingRequests--;\n"
    "            // Idleness is measured from the completion of the last request, however it ended.\n"
    "            $this->lastActiveTime = microtime(true);\n"
    "        }\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Closes the connection, aborting every in-flight request (their request() calls return false)\n"
    "     * and stopping the recv loop and the heartbeat checker.\n"
    "     *\n"
    "     * The client remains usable: the next request() reconnects.\n"
    "     *\n"
    "     * @return bool whether there was a connection (or a running recv loop) to tear down; false\n"
    "     *              when there was nothing left to close, e.g. a repeated close() or a connection\n"
    "     *              already closed by the heartbeat checker or the recv loop. Unlike in the base\n"
    "     *              class, the value does not reflect the raw socket close: that reports failure\n"
    "     *              whenever a coroutine is still bound to the socket, which on this class is the\n"
    "     *              normal case -- the recv loop reads the connection permanently.\n"
    "     */\n"
    "    public function close(): bool\n"
    "    {\n"
    "        $wasUp = $this->connected || $this->recvLoopToken !== null;\n"
    "        // Invalidate the connection before waking anyone: every requester woken during the\n"
    "        // teardown may retry immediately, and must find the token cleared and reconnect instead\n"
    "        // of sending into the socket being torn down. parent::close() itself resumes coroutines\n"
    "        // bound to the socket (the recv loop, senders mid-send()) and reports\n"
    "        // SW_ERROR_CO_SOCKET_CLOSE_WAIT on errCode while doing so -- mechanics, not a failure --\n"
    "        // so the error slot is restored afterwards.\n"
    "        $this->recvLoopToken = null;\n"
    "        $errCode             = $this->errCode;\n"
    "        $errMsg              = $this->errMsg;\n"
    "        parent::close();\n"
    "        $this->errCode = $errCode;\n"
    "        $this->errMsg  = $errMsg;\n"
    "        $this->flushStreamChannels();\n"
    "        $this->abandonedStreams = [];\n"
    "        // Clear the property before closing, as with the startup barrier: the close resumes the\n"
    "        // heartbeat checker immediately, and when a requester woken above has already started a\n"
    "        // new connection generation, the checker does not exit -- it must find the property null\n"
    "        // and create a fresh channel, not re-enter pop() on the closed one, which returns without\n"
    "        // yielding: a busy spin that would starve the event loop.\n"
    "        $sleepChannel       = $this->sleepChannel;\n"
    "        $this->sleepChannel = null;\n"
    "        $sleepChannel?->close();\n"
    "        return $wasUp;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @throws \\BadMethodCallException always\n"
    "     */\n"
    "    public function send(Request $request): int|false\n"
    "    {\n"
    "        throw new \\BadMethodCallException('requests must be sent through request() on a multiplexed connection');\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Disabled: the shared recv loop owns all reads on a multiplexed connection; reading from user\n"
    "     * code would steal its frames and corrupt the routing of responses. Use request().\n"
    "     *\n"
    "     * @throws \\BadMethodCallException always\n"
    "     */\n"
    "    public function recv(float $timeout = 0): Response|false\n"
    "    {\n"
    "        throw new \\BadMethodCallException('the shared recv loop owns all reads on a multiplexed connection; use request()');\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Disabled: the shared recv loop owns all reads on a multiplexed connection. Use request().\n"
    "     *\n"
    "     * @throws \\BadMethodCallException always\n"
    "     */\n"
    "    public function read(float $timeout = 0): Response|false\n"
    "    {\n"
    "        throw new \\BadMethodCallException('the shared recv loop owns all reads on a multiplexed connection; use request()');\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Disabled: writing to a stream that request() did not register conflicts with the shared recv\n"
    "     * loop, and its response could never be routed. Use request().\n"
    "     *\n"
    "     * @throws \\BadMethodCallException always\n"
    "     */\n"
    "    public function write(int $stream_id, mixed $data, bool $end_stream = false): bool\n"
    "    {\n"
    "        throw new \\BadMethodCallException('streams cannot be written to directly on a multiplexed connection; use request()');\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Disabled: shutting the connection down beneath the recv loop and the in-flight requests must\n"
    "     * go through close().\n"
    "     *\n"
    "     * @throws \\BadMethodCallException always\n"
    "     */\n"
    "    public function goaway(int $error_code = SWOOLE_HTTP2_ERROR_NO_ERROR, string $debug_data = ''): bool\n"
    "    {\n"
    "        throw new \\BadMethodCallException('a multiplexed connection is shut down through close()');\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Registers the channel over which the response for the given stream will be delivered.\n"
    "     */\n"
    "    private function openStreamChannel(int $streamId): Channel\n"
    "    {\n"
    "        return $this->streamChannels[$streamId] = new Channel(1);\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Unregisters a stream's channel, waking its requester (pop() returns false) if one still waits.\n"
    "     */\n"
    "    private function closeStreamChannel(int $streamId): void\n"
    "    {\n"
    "        if ($channel = $this->streamChannels[$streamId] ?? null) {\n"
    "            $channel->close();\n"
    "        }\n"
    "\n"
    "        unset($this->streamChannels[$streamId]);\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Aborts all in-flight requests by closing and unregistering their stream channels.\n"
    "     */\n"
    "    private function flushStreamChannels(): void\n"
    "    {\n"
    "        foreach (array_keys($this->streamChannels) as $streamId) {\n"
    "            $this->closeStreamChannel($streamId);\n"
    "        }\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Re-establishes the connection, discarding the current one.\n"
    "     */\n"
    "    private function reconnect(): bool\n"
    "    {\n"
    "        parent::close();\n"
    "        return parent::connect();\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Makes sure the connection is healthy and the shared recv loop is running, (re)connecting and\n"
    "     * starting the loop when needed. Serializes concurrent callers so that none of them sends while\n"
    "     * the connection is still being set up.\n"
    "     *\n"
    "     * @return bool false when no recv loop is running: the connection could not be established\n"
    "     *              (errCode/errMsg are connect()'s), or a concurrent close() aborted the startup\n"
    "     */\n"
    "    private function ensureRecvLoop(): bool\n"
    "    {\n"
    "        $this->ensureHeartbeatChecker();\n"
    "\n"
    "        // The health check and the reconnect below both yield; sending during either would fail\n"
    "        // spuriously. Coroutines arriving in the meantime must wait for the starter to finish\n"
    "        // (closing the channel wakes all waiters) and then re-check, as the state has changed.\n"
    "        while ($this->startupBarrier !== null) {\n"
    "            $this->startupBarrier->pop();\n"
    "        }\n"
    "        if ($this->recvLoopToken !== null) {\n"
    "            return true;\n"
    "        }\n"
    "\n"
    "        $this->startupBarrier = new Channel(1);\n"
    "        $spawned              = false;\n"
    "        $token                = null;\n"
    "        try {\n"
    "            $token = $this->recvLoopToken = new \\stdClass();\n"
    "            if (!$this->ping() && !$this->reconnect()) {\n"
    "                // The connection cannot be established; connect() has recorded a precise errCode\n"
    "                // (such as a refused connection). Returning here keeps the caller from send()ing,\n"
    "                // which would overwrite it with a generic no-connection error.\n"
    "                return false;\n"
    "            }\n"
    "            // close() may have cleared the token while ping()/reconnect() yielded. A loop spawned\n"
    "            // with that stale token would park in recv() -- binding the socket -- while looking\n"
    "            // stopped to everyone else, and the next request would spawn a second reader onto the\n"
    "            // same socket.\n"
    "            if ($this->recvLoopToken !== $token) {\n"
    "                $this->setError(SWOOLE_ERROR_CLIENT_NO_CONNECTION, 'the connection was closed during startup');\n"
    "                return false;\n"
    "            }\n"
    "            go(fn () => $this->recvLoop($token));\n"
    "            $spawned = true;\n"
    "            // The loop runs immediately until its first yield: on a connection that died between\n"
    "            // connect() and the first read, it exits -- and runs close() -- before go() returns, so\n"
    "            // an unconditional true here would let the caller send() on the closed client and\n"
    "            // overwrite the precise errCode with a generic one.\n"
    "            return $this->recvLoopToken === $token;\n"
    "        } finally {\n"
    "            if (!$spawned && $this->recvLoopToken === $token) {\n"
    "                // Startup died before the recv loop was spawned (an exception from the health\n"
    "                // check or reconnect): leave no token behind, or every later request would skip\n"
    "                // reconnection and send with no coroutine reading the connection.\n"
    "                $this->recvLoopToken = null;\n"
    "            }\n"
    "            // Clear the property before closing: close() resumes the waiters immediately, and a\n"
    "            // waiter that still saw the barrier set would re-enter pop() on the closed channel,\n"
    "            // which returns synchronously -- a busy spin that never yields back to this coroutine.\n"
    "            $barrier              = $this->startupBarrier;\n"
    "            $this->startupBarrier = null;\n"
    "            $barrier->close();\n"
    "        }\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Reads responses off the connection and routes each one to its requester's stream channel;\n"
    "     * runs in a coroutine of its own until the connection breaks or the client is closed.\n"
    "     *\n"
    "     * @param object $token the loop's identity: once it no longer matches $recvLoopToken, this loop\n"
    "     *                      is stale and exits without closing the client\n"
    "     */\n"
    "    private function recvLoop(object $token): void\n"
    "    {\n"
    "        $reason = 'unknown';\n"
    "        try {\n"
    "            while (true) {\n"
    "                // Wait without a read timeout: recv() called without one falls back to the socket's\n"
    "                // read timeout (the `timeout` setting, 60 seconds when unset), which would tear down\n"
    "                // a merely quiet connection as broken -- aborting every in-flight request with it --\n"
    "                // and cap how long any single response may take regardless of the timeout passed to\n"
    "                // request(). Idle teardown belongs to the heartbeat checker alone. (parent:: because\n"
    "                // the public recv() is disabled -- this loop is the connection's only reader.)\n"
    "                $response = parent::recv(-1);\n"
    "\n"
    "                if ($this->recvLoopToken !== $token) {\n"
    "                    $reason = 'the client was closed or the loop was superseded';\n"
    "                    break;\n"
    "                }\n"
    "\n"
    "                if ($response === false) {\n"
    "                    $reason = 'the connection was broken';\n"
    "                    break;\n"
    "                }\n"
    "\n"
    "                $streamId = $response->streamId;\n"
    "                if ($channel = $this->streamChannels[$streamId] ?? null) {\n"
    "                    $channel->push($response);\n"
    "                } elseif (isset($this->abandonedStreams[$streamId])) {\n"
    "                    unset($this->abandonedStreams[$streamId]);\n"
    "                } elseif ($streamId % 2 === 1) {\n"
    "                    // The response won the race against its requester registering the stream\n"
    "                    // channel (client-initiated streams have odd IDs): register the channel\n"
    "                    // here and buffer the response for the requester to pick up.\n"
    "                    $this->openStreamChannel($streamId)->push($response);\n"
    "                }\n"
    "            }\n"
    "        } catch (\\Throwable $exception) {\n"
    "            $reason = 'an exception was thrown: ' . $exception->getMessage();\n"
    "            swoole_error_log(SWOOLE_LOG_ERROR, (string) $exception);\n"
    "        } finally {\n"
    "            swoole_error_log(SWOOLE_LOG_DEBUG, 'Recv loop stopped; the next request will restart it. Reason: ' . $reason);\n"
    "            if ($this->recvLoopToken === $token) {\n"
    "                $this->close();\n"
    "            }\n"
    "        }\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Makes sure the heartbeat checker is running, unless disabled: a coroutine that closes the\n"
    "     * connection once no requests are in flight and none was sent for `heartbeat_idle_time` seconds.\n"
    "     */\n"
    "    private function ensureHeartbeatChecker(): void\n"
    "    {\n"
    "        if ($this->heartbeatCheckerRunning) {\n"
    "            return;\n"
    "        }\n"
    "        $maxIdleTime = (float) ($this->setting[Constant::OPTION_HEARTBEAT_IDLE_TIME] ?? self::DEFAULT_HEARTBEAT_IDLE_TIME);\n"
    "        if ($maxIdleTime <= 0) {\n"
    "            return;\n"
    "        }\n"
    "        $checkInterval = (float) ($this->setting[Constant::OPTION_HEARTBEAT_CHECK_INTERVAL] ?? self::DEFAULT_HEARTBEAT_CHECK_INTERVAL);\n"
    "        if ($checkInterval <= 0) {\n"
    "            // A non-positive interval would make interruptibleSleep() wait forever -- silently\n"
    "            // disabling idle closing through the wrong option while pinning the checker coroutine.\n"
    "            $checkInterval = self::DEFAULT_HEARTBEAT_CHECK_INTERVAL;\n"
    "        }\n"
    "\n"
    "        $this->heartbeatCheckerRunning = true;\n"
    "        go(\n"
    "            function () use ($checkInterval, $maxIdleTime) {\n"
    "                try {\n"
    "                    while (true) {\n"
    "                        $this->interruptibleSleep($checkInterval);\n"
    "                        if ($this->recvLoopToken === null) {\n"
    "                            break;\n"
    "                        }\n"
    "                        // The pending-requests counter covers requests still connecting or sending;\n"
    "                        // the stream-channel registry covers responses parked for pickup.\n"
    "                        if ($this->pendingRequests === 0 && $this->streamChannels === [] && microtime(true) - $this->lastActiveTime > $maxIdleTime) {\n"
    "                            $this->close();\n"
    "                            break;\n"
    "                        }\n"
    "                    }\n"
    "                } finally {\n"
    "                    $this->heartbeatCheckerRunning = false;\n"
    "                }\n"
    "            }\n"
    "        );\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Records the failure of the current operation on the client's errCode/errMsg properties.\n"
    "     */\n"
    "    private function setError(int $errCode, string $errMsg): void\n"
    "    {\n"
    "        $this->errCode = $errCode;\n"
    "        $this->errMsg  = $errMsg;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Sleeps for the given number of seconds, or until close() wakes the sleeper up early by\n"
    "     * closing the sleep channel.\n"
    "     */\n"
    "    private function interruptibleSleep(float $seconds): void\n"
    "    {\n"
    "        $this->sleepChannel = $this->sleepChannel ?? new Channel(1);\n"
    "        $this->sleepChannel->pop($seconds);\n"
    "    }\n"
    "}\n";

static const char* swoole_library_source_core_connection_pool =
    "\n"
    "/**\n"
    " * This file is part of Swoole.\n"
    " *\n"
    " * @link     https://www.swoole.com\n"
    " * @contact  team@swoole.com\n"
    " * @license  https://github.com/swoole/library/blob/master/LICENSE\n"
    " */\n"
    "\n"
    "declare(strict_types=1);\n"
    "\n"
    "namespace Swoole;\n"
    "\n"
    "use Swoole\\Coroutine\\Channel;\n"
    "\n"
    "class ConnectionPool\n"
    "{\n"
    "    public const DEFAULT_SIZE = 64;\n"
    "\n"
    "    protected ?Channel $pool;\n"
    "\n"
    "    /** @var callable */\n"
    "    protected $constructor;\n"
    "\n"
    "    protected int $num = 0;\n"
    "\n"
    "    /** @var \\WeakMap<object, bool> true while checked out, false while queued */\n"
    "    private \\WeakMap $connections;\n"
    "\n"
    "    /** @var callable|null */\n"
    "    private $destructor;\n"
    "\n"
    "    /**\n"
    "     * @param callable(): object $constructor Creates a distinct connection object.\n"
    "     * @param (callable(object): void)|null $destructor Releases a discarded or idle connection; active loans are\n"
    "     *                                                  released when returned after close().\n"
    "     */\n"
    "    public function __construct(callable $constructor, protected int $size = self::DEFAULT_SIZE, protected ?string $proxy = null, ?callable $destructor = null)\n"
    "    {\n"
    "        if ($size <= 0) {\n"
    "            throw new \\InvalidArgumentException('Connection pool size must be positive');\n"
    "        }\n"
    "        $this->connections = new \\WeakMap();\n"
    "        $this->destructor  = $destructor;\n"
    "        $this->pool        = new Channel($this->size);\n"
    "        $this->constructor = $constructor;\n"
    "    }\n"
    "\n"
    "    public function fill(): void\n"
    "    {\n"
    "        if ($this->pool === null) {\n"
    "            // A closed pool has nowhere to keep the connections: they would be made, counted and dropped.\n"
    "            return;\n"
    "        }\n"
    "        while ($this->pool !== null && $this->size > $this->num) {\n"
    "            $this->make();\n"
    "        }\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Get a connection from the pool.\n"
    "     *\n"
    "     * @param float $timeout the number of seconds to wait for a connection; 0 or less waits with no time limit\n"
    "     * @return mixed a connection object from the pool, or false if no connection is available before the timeout is\n"
    "     *               reached, the pool is closed while waiting, or the waiting coroutine is canceled\n"
    "     */\n"
    "    public function get(float $timeout = -1)\n"
    "    {\n"
    "        if ($this->pool === null) {\n"
    "            throw new \\RuntimeException('Pool has been closed');\n"
    "        }\n"
    "        if ($this->pool->isEmpty() && $this->num < $this->size) {\n"
    "            $this->make();\n"
    "        }\n"
    "        $connection = $this->pool?->pop($timeout) ?? false;\n"
    "        if (is_object($connection)) {\n"
    "            $this->connections[$connection] = true;\n"
    "        }\n"
    "        return $connection;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Runs the callback with a connection from the pool, and puts the connection back when the callback is done,\n"
    "     * whether it returned or threw. A connection taken with get() and not put back stays counted by the pool, and\n"
    "     * once that has happened as many times as the pool is large, get() finds no connection any more.\n"
    "     *\n"
    "     * The connection is put back as it is, also when the callback threw. The pools of the library clean it in put():\n"
    "     * they roll back a transaction left open, and replace a connection that cannot be cleaned.\n"
    "     *\n"
    "     * The callback must not put the connection back itself, nor use it, or anything bound to it, such as a\n"
    "     * statement, a generator or another coroutine, after it returned: the connection is someone else's by then.\n"
    "     * A callback that calls withConnection() of the same pool needs a second free connection, or it waits forever;\n"
    "     * give the inner call a timeout. Code that has to discard a broken connection uses get() and discard().\n"
    "     *\n"
    "     * @template T\n"
    "     * @param callable(mixed): T $callback called with the connection; what it returns is returned\n"
    "     * @param float $timeout the number of seconds to wait for a connection; 0 or less waits with no time limit\n"
    "     * @return T\n"
    "     * @throws \\RuntimeException when no connection is available before the timeout is reached, or the pool is\n"
    "     *                           closed, or the coroutine is canceled while waiting\n"
    "     */\n"
    "    public function withConnection(callable $callback, float $timeout = -1): mixed\n"
    "    {\n"
    "        $connection = $this->get($timeout);\n"
    "        if ($connection === false) {\n"
    "            // Read before anything yields: close() wakes the coroutines waiting in get() before it drops the channel.\n"
    "            $errCode = $this->pool?->errCode;\n"
    "            if ($errCode === null || $errCode === SWOOLE_CHANNEL_CLOSED) {\n"
    "                throw new \\RuntimeException('Pool has been closed');\n"
    "            }\n"
    "            if ($errCode === SWOOLE_CHANNEL_CANCELED) {\n"
    "                throw new \\RuntimeException('Canceled while waiting for a connection from the pool');\n"
    "            }\n"
    "            throw new \\RuntimeException(sprintf('No connection is available from the pool within %g seconds', $timeout));\n"
    "        }\n"
    "\n"
    "        try {\n"
    "            return $callback($connection);\n"
    "        } finally {\n"
    "            $this->put($connection);\n"
    "        }\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Return a checked-out connection. Foreign or duplicate returns throw before changing the pool.\n"
    "     * A null return is supported only when exactly one lost or checked-out connection can be identified;\n"
    "     * use discard($connection) when several connections are borrowed.\n"
    "     */\n"
    "    public function put(mixed $connection): void\n"
    "    {\n"
    "        if ($this->pool === null) {\n"
    "            if (is_object($connection) && isset($this->connections[$connection])) {\n"
    "                unset($this->connections[$connection]);\n"
    "                $this->dispose($connection);\n"
    "            }\n"
    "            return;\n"
    "        }\n"
    "        if ($connection === null) {\n"
    "            $borrowed = [];\n"
    "            foreach ($this->connections as $object => $checkedOut) {\n"
    "                if ($checkedOut) {\n"
    "                    $borrowed[] = $object;\n"
    "                }\n"
    "            }\n"
    "            if (count($borrowed) === 1 && $this->num === count($this->connections)) {\n"
    "                $this->discard($borrowed[0]);\n"
    "                return;\n"
    "            }\n"
    "            // A borrower may already have released its last reference to the broken object.\n"
    "            if ($borrowed === [] && $this->num - count($this->connections) === 1) {\n"
    "                $this->num--;\n"
    "                $this->make();\n"
    "                return;\n"
    "            }\n"
    "            throw new \\InvalidArgumentException('Cannot identify the broken connection; use discard($connection)');\n"
    "        }\n"
    "        $this->assertCanReturn($connection);\n"
    "        $this->connections[$connection] = false;\n"
    "        $this->pool->push($connection);\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Discard this checked-out connection and replace it. Unlike put(null), this also works with multiple borrowers.\n"
    "     */\n"
    "    public function discard(object $connection): void\n"
    "    {\n"
    "        $this->assertCanReturn($connection);\n"
    "        unset($this->connections[$connection]);\n"
    "        if ($this->pool === null) {\n"
    "            $this->dispose($connection);\n"
    "            return;\n"
    "        }\n"
    "        $this->num--;\n"
    "        try {\n"
    "            $this->dispose($connection);\n"
    "        } finally {\n"
    "            if ($this->pool !== null && $this->num < $this->size) {\n"
    "                $this->make();\n"
    "            }\n"
    "        }\n"
    "    }\n"
    "\n"
    "    public function close(): void\n"
    "    {\n"
    "        if ($this->pool === null) {\n"
    "            return;\n"
    "        }\n"
    "        $pool       = $this->pool;\n"
    "        $this->pool = null;\n"
    "        $this->num  = 0;\n"
    "        $failure    = null;\n"
    "        try {\n"
    "            while (!$pool->isEmpty()) {\n"
    "                $connection = $pool->pop();\n"
    "                unset($this->connections[$connection]);\n"
    "                try {\n"
    "                    $this->dispose($connection);\n"
    "                } catch (\\Throwable $e) {\n"
    "                    $failure = $failure ?? $e;\n"
    "                }\n"
    "            }\n"
    "        } finally {\n"
    "            $pool->close();\n"
    "        }\n"
    "        if ($failure !== null) {\n"
    "            throw $failure;\n"
    "        }\n"
    "    }\n"
    "\n"
    "    protected function assertCanReturn(mixed $connection): void\n"
    "    {\n"
    "        if (!is_object($connection) || !isset($this->connections[$connection])) {\n"
    "            throw new \\InvalidArgumentException('The connection does not belong to this pool');\n"
    "        }\n"
    "        if (!$this->connections[$connection]) {\n"
    "            throw new \\LogicException('The connection has already been returned to this pool');\n"
    "        }\n"
    "    }\n"
    "\n"
    "    protected function make(): void\n"
    "    {\n"
    "        $this->num++;\n"
    "        try {\n"
    "            if ($this->proxy) {\n"
    "                $connection = new $this->proxy($this->constructor);\n"
    "            } else {\n"
    "                $connection = ($this->constructor)();\n"
    "            }\n"
    "        } catch (\\Throwable $throwable) {\n"
    "            if ($this->pool !== null) {\n"
    "                $this->num--;\n"
    "            }\n"
    "            throw $throwable;\n"
    "        }\n"
    "        if (!is_object($connection) || isset($this->connections[$connection])) {\n"
    "            if ($this->pool !== null) {\n"
    "                $this->num--;\n"
    "            }\n"
    "            throw new \\UnexpectedValueException('The connection constructor must return a new object');\n"
    "        }\n"
    "        $this->connections[$connection] = true;\n"
    "        $this->put($connection);\n"
    "    }\n"
    "\n"
    "    private function dispose(object $connection): void\n"
    "    {\n"
    "        if ($this->destructor !== null) {\n"
    "            ($this->destructor)($connection);\n"
    "        }\n"
    "    }\n"
    "}\n";

