static const char* swoole_library_source_core_database_mysqli_pool =
    "\n"
    "/**\n"
    " * This file is part of Swoole.\n"
    " *\n"
    " * @link     https://www.swoole.com\n"
    " * @contact  team@swoole.com\n"
    " * @license  https://github.com/swoole/library/blob/master/LICENSE\n"
    " */\n"
    "\n"
    "declare(strict_types=1);\n"
    "\n"
    "namespace Swoole\\Database;\n"
    "\n"
    "use Swoole\\ConnectionPool;\n"
    "\n"
    "/**\n"
    " * @method \\mysqli|MysqliProxy|false get(float $timeout = -1)\n"
    " */\n"
    "class MysqliPool extends ConnectionPool\n"
    "{\n"
    "    public function __construct(protected MysqliConfig $config, int $size = self::DEFAULT_SIZE)\n"
    "    {\n"
    "        parent::__construct(function () {\n"
    "            $mysqli = new \\mysqli();\n"
    "            foreach ($this->config->getOptions() as $option => $value) {\n"
    "                $mysqli->set_opt($option, $value);\n"
    "            }\n"
    "            $mysqli->real_connect(\n"
    "                $this->config->getHost(),\n"
    "                $this->config->getUsername(),\n"
    "                $this->config->getPassword(),\n"
    "                $this->config->getDbname(),\n"
    "                $this->config->getPort(),\n"
    "                $this->config->getUnixSocket()\n"
    "            );\n"
    "            if ($mysqli->connect_errno) {\n"
    "                throw new MysqliException($mysqli->connect_error, $mysqli->connect_errno);\n"
    "            }\n"
    "            $mysqli->set_charset($this->config->getCharset());\n"
    "            return $mysqli;\n"
    "        }, $size, MysqliProxy::class, static function (MysqliProxy $connection): void {\n"
    "            try {\n"
    "                $connection->__getObject()->close();\n"
    "            } catch (\\Error) {\n"
    "                // The borrower may already have closed this mysqli object.\n"
    "            }\n"
    "        });\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Get a mysqli connection from the pool, wrapped in a MysqliProxy. The proxy's transaction tracking is reset,\n"
    "     * as PDOPool does, so that a connection put back in the middle of a transaction does not keep the next\n"
    "     * borrower from reconnecting when the connection is lost.\n"
    "     *\n"
    "     * @param float $timeout the number of seconds to wait for a connection; 0 or less waits with no time limit\n"
    "     * @return MysqliProxy|false Returns a MysqliProxy object from the pool, or false if no connection is available before the timeout.\n"
    "     */\n"
    "    public function get(float $timeout = -1)\n"
    "    {\n"
    "        /* @var MysqliProxy|false $mysqli */\n"
    "        $mysqli = parent::get($timeout);\n"
    "        if ($mysqli === false) {\n"
    "            return false;\n"
    "        }\n"
    "\n"
    "        $mysqli->reset();\n"
    "        $mysqli->setRetryOnLostConnection($this->config->getRetryOnLostConnection());\n"
    "\n"
    "        return $mysqli;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Return a connection to the pool.\n"
    "     *\n"
    "     * A transaction left open on the connection is rolled back first, and autocommit is turned back on, so that\n"
    "     * the next borrower does not work inside a transaction it never began. A connection that cannot be cleaned\n"
    "     * is replaced; when the replacement cannot be made, it is left to the next get() to make it and to report\n"
    "     * the failure.\n"
    "     *\n"
    "     * The transaction is the one the proxy tracks, see MysqliProxy::inTransaction(): one started by hand, with\n"
    "     * query('START TRANSACTION') or query('SET autocommit=0'), is not seen and stays open.\n"
    "     *\n"
    "     * @param MysqliProxy|null $connection the connection to return, or null to have a broken connection replaced\n"
    "     */\n"
    "    public function put(mixed $connection): void\n"
    "    {\n"
    "        if ($connection !== null && $this->pool !== null) {\n"
    "            $this->assertCanReturn($connection);\n"
    "        }\n"
    "        if ($this->pool !== null && $connection instanceof MysqliProxy && !$this->clean($connection)) {\n"
    "            try {\n"
    "                parent::discard($connection);\n"
    "            } catch (\\Throwable) {\n"
    "                // Putting a connection back is no place to report that a new one cannot be made.\n"
    "            }\n"
    "            return;\n"
    "        }\n"
    "\n"
    "        parent::put($connection);\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Rolls back the transaction left open on the connection, if any, and turns autocommit back on.\n"
    "     *\n"
    "     * @return bool false when that fails, as when the connection was lost, or closed, inside the transaction\n"
    "     */\n"
    "    private function clean(MysqliProxy $connection): bool\n"
    "    {\n"
    "        if ($connection->isLost()) {\n"
    "            return false;\n"
    "        }\n"
    "        if ($connection->inTransaction()) {\n"
    "            $mysqli = $connection->__getObject();\n"
    "            try {\n"
    "                if (!@$mysqli->rollback() || !@$mysqli->autocommit(true)) {\n"
    "                    return false;\n"
    "                }\n"
    "            } catch (\\Throwable) {\n"
    "                // A mysqli_sql_exception, or the Error of a connection that was closed.\n"
    "                return false;\n"
    "            }\n"
    "            $connection->reset();\n"
    "            // reset() forgets the transaction flags. The mode has to be recorded after that, or the\n"
    "            // next reconnect would replay the autocommit(false) the previous borrower left behind.\n"
    "            $connection->rememberAutocommit(true);\n"
    "        }\n"
    "\n"
    "        return true;\n"
    "    }\n"
    "}\n";

static const char* swoole_library_source_core_database_mysqli_proxy =
    "\n"
    "/**\n"
    " * This file is part of Swoole.\n"
    " *\n"
    " * @link     https://www.swoole.com\n"
    " * @contact  team@swoole.com\n"
    " * @license  https://github.com/swoole/library/blob/master/LICENSE\n"
    " */\n"
    "\n"
    "declare(strict_types=1);\n"
    "\n"
    "namespace Swoole\\Database;\n"
    "\n"
    "/**\n"
    " * A lost connection is reported without replaying an ambiguous call. A later explicit call reconnects.\n"
    " * setRetryOnLostConnection(true) opts in to replay outside transactions; only use it for repeatable work.\n"
    " * Pools restore the policy from MysqliConfig::withRetryOnLostConnection() on every checkout.\n"
    " *\n"
    " * @method \\mysqli __getObject()\n"
    " */\n"
    "class MysqliProxy extends ObjectProxy\n"
    "{\n"
    "    public const IO_METHOD_REGEX = '/^(autocommit|begin_transaction|change_user|commit|execute_query|kill|multi_query|ping|prepare|query|real_connect|real_query|reap_async_query|refresh|release_savepoint|rollback|savepoint|select_db|send_query|set_charset|ssl_set)$/i';\n"
    "\n"
    "    public const IO_ERRORS = [\n"
    "        2002, // MYSQLND_CR_CONNECTION_ERROR\n"
    "        2006, // MYSQLND_CR_SERVER_GONE_ERROR\n"
    "        2013, // MYSQLND_CR_SERVER_LOST\n"
    "    ];\n"
    "\n"
    "    /** @var \\mysqli */\n"
    "    protected $__object;\n"
    "\n"
    "    protected string $charsetContext = '';\n"
    "\n"
    "    protected array $setOptContext = [];\n"
    "\n"
    "    /** @var array{string, \\SensitiveParameterValue, ?string}|array{} */\n"
    "    protected array $changeUserContext = [];\n"
    "\n"
    "    /** @var callable */\n"
    "    protected $constructor;\n"
    "\n"
    "    protected int $round = 0;\n"
    "\n"
    "    protected bool $retryOnLostConnection = false;\n"
    "\n"
    "    /**\n"
    "     * Whether a transaction was started with begin_transaction() and not yet ended with commit() or rollback().\n"
    "     */\n"
    "    protected bool $inTransaction = false;\n"
    "\n"
    "    /**\n"
    "     * Whether autocommit was turned off with autocommit(false): every statement then runs inside an implicit\n"
    "     * transaction, and commit() or rollback() only ends the current one, so the connection counts as in a\n"
    "     * transaction until autocommit(true).\n"
    "     */\n"
    "    protected bool $autocommitDisabled = false;\n"
    "\n"
    "    /**\n"
    "     * The last autocommit() that succeeded. Reconnect restores it. Null until autocommit() is called,\n"
    "     * so a connection that never changed the server default is left on that default.\n"
    "     */\n"
    "    protected ?bool $autocommitMode = null;\n"
    "\n"
    "    private bool $lost = false;\n"
    "\n"
    "    public function __construct(callable $constructor)\n"
    "    {\n"
    "        parent::__construct($constructor());\n"
    "        $this->constructor = $constructor;\n"
    "    }\n"
    "\n"
    "    public function __call(string $name, array $arguments)\n"
    "    {\n"
    "        if ($this->lost && strcasecmp($name, 'close') !== 0) {\n"
    "            $this->reconnect();\n"
    "        }\n"
    "        for ($n = 3; $n--;) {\n"
    "            // Under the default report mode (MYSQLI_REPORT_ERROR | MYSQLI_REPORT_STRICT since PHP 8.1) a failure\n"
    "            // throws a mysqli_sql_exception instead of returning false; both forms are handled the same way below.\n"
    "            $exception = null;\n"
    "            try {\n"
    "                $ret = $this->__object->{$name}(...$arguments);\n"
    "            } catch (\\mysqli_sql_exception $exception) {\n"
    "                $ret = false;\n"
    "            }\n"
    "            if ($ret === false) {\n"
    "                $errno = $exception ? $exception->getCode() : $this->__object->errno;\n"
    "                /* non-IO method */\n"
    "                if (!preg_match(static::IO_METHOD_REGEX, $name)) {\n"
    "                    if ($exception) {\n"
    "                        throw $exception;\n"
    "                    }\n"
    "                    if (in_array($errno, static::IO_ERRORS, true)) {\n"
    "                        // A method outside the retry list, e.g. store_result(), next_result() or stat(), can return\n"
    "                        // false with no error at all, but false with a lost-connection errno is the connection going\n"
    "                        // away, which is reported rather than passed through as if there were nothing to return.\n"
    "                        // Only the retry is limited to methods that run the statement from the start.\n"
    "                        throw new MysqliException($this->__object->error, $errno);\n"
    "                    }\n"
    "                    break;\n"
    "                }\n"
    "                /* no more chances or non-IO failures */\n"
    "                if (!in_array($errno, static::IO_ERRORS, true) || ($n === 0)) {\n"
    "                    if ($exception) {\n"
    "                        throw $exception;\n"
    "                    }\n"
    "                    throw new MysqliException($this->__object->error, $errno);\n"
    "                }\n"
    "                if ($this->inTransaction() || !$this->retryOnLostConnection) {\n"
    "                    // The transaction died with the connection. Reconnecting and re-running this one call would\n"
    "                    // silently drop what ran before it in the transaction, and run this call, and the commit(), on\n"
    "                    // a fresh connection outside of any transaction. The caller has to see the lost connection and\n"
    "                    // redo the whole unit of work; the next call, outside the transaction, reconnects as usual.\n"
    "                    $this->markAsLost();\n"
    "                    if ($exception) {\n"
    "                        throw $exception;\n"
    "                    }\n"
    "                    throw new MysqliException($this->__object->error, $errno);\n"
    "                }\n"
    "                $this->reconnect();\n"
    "                continue;\n"
    "            }\n"
    "            if (strcasecmp($name, 'prepare') === 0) {\n"
    "                // By position or by name: mysqli::prepare(string $query).\n"
    "                $ret = new MysqliStatementProxy($ret, $arguments[0] ?? $arguments['query'] ?? null, $this);\n"
    "            } elseif (strcasecmp($name, 'stmt_init') === 0) {\n"
    "                $ret = new MysqliStatementProxy($ret, null, $this);\n"
    "            } elseif (strcasecmp($name, 'begin_transaction') === 0) {\n"
    "                $this->inTransaction = true;\n"
    "            } elseif (strcasecmp($name, 'commit') === 0 || strcasecmp($name, 'rollback') === 0) {\n"
    "                $this->inTransaction = false;\n"
    "            } elseif (strcasecmp($name, 'autocommit') === 0) {\n"
    "                // By position or by name: mysqli::autocommit(bool $enable).\n"
    "                $enable                   = (bool) ($arguments[0] ?? $arguments['enable'] ?? true);\n"
    "                $this->autocommitDisabled = !$enable;\n"
    "                $this->autocommitMode     = $enable;\n"
    "            }\n"
    "            break;\n"
    "        }\n"
    "        /* @noinspection PhpUndefinedVariableInspection */\n"
    "        return $ret;\n"
    "    }\n"
    "\n"
    "    /** Opt in only when repeating the operation cannot duplicate effects. */\n"
    "    public function setRetryOnLostConnection(bool $retry): void\n"
    "    {\n"
    "        $this->retryOnLostConnection = $retry;\n"
    "    }\n"
    "\n"
    "    public function shouldRetryOnLostConnection(): bool\n"
    "    {\n"
    "        return $this->retryOnLostConnection;\n"
    "    }\n"
    "\n"
    "    /** @internal */\n"
    "    public function isLost(): bool\n"
    "    {\n"
    "        return $this->lost;\n"
    "    }\n"
    "\n"
    "    /** @internal */\n"
    "    public function markAsLost(): void\n"
    "    {\n"
    "        $this->lost = true;\n"
    "        $this->reset();\n"
    "    }\n"
    "\n"
    "    public function getRound(): int\n"
    "    {\n"
    "        return $this->round;\n"
    "    }\n"
    "\n"
    "    public function reconnect(): void\n"
    "    {\n"
    "        $this->lost = true;\n"
    "        parent::__construct(($this->constructor)());\n"
    "        $this->lost = false;\n"
    "        $this->round++;\n"
    "        $this->reset();\n"
    "        /* restore context */\n"
    "        if (!empty($this->charsetContext)) {\n"
    "            $this->__object->set_charset($this->charsetContext);\n"
    "        }\n"
    "        foreach ($this->setOptContext as $opt => $val) {\n"
    "            $this->__object->set_opt($opt, $val);\n"
    "        }\n"
    "        if (!empty($this->changeUserContext)) {\n"
    "            [$username, $password, $database] = $this->changeUserContext;\n"
    "            $this->__object->change_user($username, $password->getValue(), $database);\n"
    "        }\n"
    "        if ($this->autocommitMode !== null) {\n"
    "            $this->__object->autocommit($this->autocommitMode);\n"
    "            $this->autocommitDisabled = !$this->autocommitMode;\n"
    "        }\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Records the autocommit mode without sending it. The pool calls this after it has turned autocommit\n"
    "     * back on while cleaning a returned connection, so a later reconnect does not turn it off again.\n"
    "     *\n"
    "     * @internal\n"
    "     */\n"
    "    public function rememberAutocommit(bool $enable): void\n"
    "    {\n"
    "        $this->autocommitMode     = $enable;\n"
    "        $this->autocommitDisabled = !$enable;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Whether the connection is inside a transaction: one started with begin_transaction(), or the implicit one\n"
    "     * that runs while autocommit is turned off with autocommit(false). A transaction started by hand, with\n"
    "     * query('START TRANSACTION') or query('SET autocommit=0'), is not seen here, the same limitation PDO's\n"
    "     * inTransaction() has. A lost connection inside a transaction is reported instead of reconnected.\n"
    "     */\n"
    "    public function inTransaction(): bool\n"
    "    {\n"
    "        return $this->inTransaction || $this->autocommitDisabled;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Forgets the transaction state tracked by inTransaction(): after a reconnect, when the transaction died with\n"
    "     * the connection, and when the pool hands the connection out.\n"
    "     */\n"
    "    public function reset(): void\n"
    "    {\n"
    "        $this->inTransaction      = false;\n"
    "        $this->autocommitDisabled = false;\n"
    "    }\n"
    "\n"
    "    public function options(int $option, mixed $value): bool\n"
    "    {\n"
    "        $this->setOptContext[$option] = $value;\n"
    "        return $this->__object->options($option, $value);\n"
    "    }\n"
    "\n"
    "    public function set_opt(int $option, mixed $value): bool\n"
    "    {\n"
    "        return $this->options($option, $value);\n"
    "    }\n"
    "\n"
    "    public function set_charset(string $charset): bool\n"
    "    {\n"
    "        $this->charsetContext = $charset;\n"
    "        return $this->__object->set_charset($charset);\n"
    "    }\n"
    "\n"
    "    public function change_user(string $username, #[\\SensitiveParameter] string $password, ?string $database): bool\n"
    "    {\n"
    "        $result = $this->__object->change_user($username, $password, $database);\n"
    "        if ($result) {\n"
    "            $this->changeUserContext = [$username, new \\SensitiveParameterValue($password), $database];\n"
    "        }\n"
    "        return $result;\n"
    "    }\n"
    "}\n";

static const char* swoole_library_source_core_database_mysqli_statement_proxy =
    "\n"
    "/**\n"
    " * This file is part of Swoole.\n"
    " *\n"
    " * @link     https://www.swoole.com\n"
    " * @contact  team@swoole.com\n"
    " * @license  https://github.com/swoole/library/blob/master/LICENSE\n"
    " */\n"
    "\n"
    "declare(strict_types=1);\n"
    "\n"
    "namespace Swoole\\Database;\n"
    "\n"
    "class MysqliStatementProxy extends ObjectProxy\n"
    "{\n"
    "    /**\n"
    "     * The methods that are run again on a fresh connection after a lost one. fetch() is not one of them: it reads\n"
    "     * the result of an execute() that went down with the connection, and running it on a statement that was\n"
    "     * prepared again but never executed fails with \"Commands out of sync\" in place of the lost connection.\n"
    "     */\n"
    "    public const IO_METHOD_REGEX = '/^(execute|prepare)$/i';\n"
    "\n"
    "    /** @var \\mysqli_stmt */\n"
    "    protected $__object;\n"
    "\n"
    "    protected array $attrSetContext = [];\n"
    "\n"
    "    protected array $bindParamContext = [];\n"
    "\n"
    "    protected array $bindResultContext = [];\n"
    "\n"
    "    protected int $parentRound;\n"
    "\n"
    "    public function __construct(\\mysqli_stmt $object, protected ?string $queryString, protected MysqliProxy $parent)\n"
    "    {\n"
    "        parent::__construct($object);\n"
    "        $this->parentRound = $parent->getRound();\n"
    "    }\n"
    "\n"
    "    public function __call(string $name, array $arguments)\n"
    "    {\n"
    "        if (in_array(strtolower($name), ['execute', 'prepare'], true)\n"
    "            && ($this->parent->isLost() || $this->parent->getRound() !== $this->parentRound)) {\n"
    "            $this->reprepare();\n"
    "        }\n"
    "        for ($n = 3; $n--;) {\n"
    "            // Under the default report mode (MYSQLI_REPORT_ERROR | MYSQLI_REPORT_STRICT since PHP 8.1) a failure\n"
    "            // throws a mysqli_sql_exception instead of returning false; both forms are handled the same way below.\n"
    "            $exception = null;\n"
    "            try {\n"
    "                $ret = $this->__object->{$name}(...$arguments);\n"
    "            } catch (\\mysqli_sql_exception $exception) {\n"
    "                $ret = false;\n"
    "            }\n"
    "            if ($ret === false) {\n"
    "                $errno = $exception ? $exception->getCode() : $this->__object->errno;\n"
    "                /* non-IO method */\n"
    "                if (!preg_match(static::IO_METHOD_REGEX, $name)) {\n"
    "                    if ($exception) {\n"
    "                        throw $exception;\n"
    "                    }\n"
    "                    if (in_array($errno, $this->parent::IO_ERRORS, true)) {\n"
    "                        // False from fetch(), get_result(), store_result() and the like can mean there is nothing to\n"
    "                        // return; with a lost-connection errno it means the connection is gone, and that is reported.\n"
    "                        throw new MysqliException($this->__object->error, $errno);\n"
    "                    }\n"
    "                    break;\n"
    "                }\n"
    "                /* no more chances or non-IO failures */\n"
    "                if (!in_array($errno, $this->parent::IO_ERRORS, true) || ($n === 0)) {\n"
    "                    if ($exception) {\n"
    "                        throw $exception;\n"
    "                    }\n"
    "                    throw new MysqliException($this->__object->error, $errno);\n"
    "                }\n"
    "                if ($this->parent->inTransaction() || !$this->parent->shouldRetryOnLostConnection()) {\n"
    "                    // The transaction died with the connection; see MysqliProxy::__call() for why this is not retried.\n"
    "                    $this->parent->markAsLost();\n"
    "                    if ($exception) {\n"
    "                        throw $exception;\n"
    "                    }\n"
    "                    throw new MysqliException($this->__object->error, $errno);\n"
    "                }\n"
    "                $this->reprepare();\n"
    "                continue;\n"
    "            }\n"
    "            if (strcasecmp($name, 'prepare') === 0) {\n"
    "                // By position or by name: mysqli_stmt::prepare(string $query).\n"
    "                $this->queryString = $arguments[0] ?? $arguments['query'] ?? null;\n"
    "            }\n"
    "            break;\n"
    "        }\n"
    "        /* @noinspection PhpUndefinedVariableInspection */\n"
    "        return $ret;\n"
    "    }\n"
    "\n"
    "    public function attr_set(int $attribute, int $value): bool\n"
    "    {\n"
    "        $this->attrSetContext[$attribute] = $value;\n"
    "        return $this->__object->attr_set($attribute, $value);\n"
    "    }\n"
    "\n"
    "    public function bind_param(string $types, mixed &...$vars): bool\n"
    "    {\n"
    "        $this->bindParamContext = [$types, $vars];\n"
    "        return $this->__object->bind_param($types, ...$vars);\n"
    "    }\n"
    "\n"
    "    public function bind_result(mixed &...$vars): bool\n"
    "    {\n"
    "        $this->bindResultContext = $vars;\n"
    "        return $this->__object->bind_result(...$vars);\n"
    "    }\n"
    "\n"
    "    private function reprepare(): void\n"
    "    {\n"
    "        if ($this->parent->getRound() === $this->parentRound || $this->parent->isLost()) {\n"
    "            /* if not equal, parent has reconnected */\n"
    "            $this->parent->reconnect();\n"
    "        }\n"
    "        $this->parentRound = $this->parent->getRound();\n"
    "        $parent            = $this->parent->__getObject();\n"
    "        $statement         = $this->queryString !== null ? $parent->prepare($this->queryString) : $parent->stmt_init();\n"
    "        if ($statement === false) {\n"
    "            throw new MysqliException($parent->error, $parent->errno);\n"
    "        }\n"
    "        $this->__object = $statement;\n"
    "        if (!empty($this->bindParamContext)) {\n"
    "            $this->__object->bind_param($this->bindParamContext[0], ...$this->bindParamContext[1]);\n"
    "        }\n"
    "        if (!empty($this->bindResultContext)) {\n"
    "            $this->__object->bind_result(...$this->bindResultContext);\n"
    "        }\n"
    "        foreach ($this->attrSetContext as $attr => $value) {\n"
    "            $this->__object->attr_set($attr, $value);\n"
    "        }\n"
    "    }\n"
    "}\n";

static const char* swoole_library_source_core_database_detects_lost_connections =
    "\n"
    "/**\n"
    " * This file is part of Swoole.\n"
    " *\n"
    " * @link     https://www.swoole.com\n"
    " * @contact  team@swoole.com\n"
    " * @license  https://github.com/swoole/library/blob/master/LICENSE\n"
    " */\n"
    "\n"
    "declare(strict_types=1);\n"
    "\n"
    "namespace Swoole\\Database;\n"
    "\n"
    "class DetectsLostConnections\n"
    "{\n"
    "    private const DRIVER_ERRORS = [2002, 2006, 2013, 2024, 2055, 3113, 3114];\n"
    "\n"
    "    /** Specific transport diagnostics, never generic words such as \"timed out\" or \"went away\". */\n"
    "    private const ERROR_MESSAGES = [\n"
    "        'server has gone away',\n"
    "        'no connection to the server',\n"
    "        'lost connection to mysql server',\n"
    "        'server closed the connection unexpectedly',\n"
    "        'ssl connection has been closed unexpectedly',\n"
    "        'error writing data to the connection',\n"
    "        'decryption failed or bad record mac',\n"
    "        'physical connection is not usable',\n"
    "        'communication link failure',\n"
    "        'connection is no longer usable',\n"
    "        'ssl syscall error: eof detected',\n"
    "        'ssl error: unexpected eof',\n"
    "        'ssl error: sslv3 alert unexpected message',\n"
    "        'ssl error: ssl/tls alert unexpected message',\n"
    "        'unrecognized ssl error code:',\n"
    "        'channel connection is closed',\n"
    "    ];\n"
    "\n"
    "    public static function causedByLostConnection(\\Throwable $e): bool\n"
    "    {\n"
    "        if ($e instanceof \\PDOException && is_array($e->errorInfo)) {\n"
    "            return self::causedByErrorInfo($e->errorInfo);\n"
    "        }\n"
    "        if ($e instanceof \\mysqli_sql_exception) {\n"
    "            return self::matches($e->getMessage(), $e->getSqlState(), $e->getCode());\n"
    "        }\n"
    "        $code  = (string) $e->getCode();\n"
    "        $state = preg_match('/^[A-Z0-9]{5}$/i', $code) ? $code : '';\n"
    "        return self::matches($e->getMessage(), $state, $state === '' ? (int) $code : 0);\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @param array{0?: string, 1?: int|string|null, 2?: string|null}|array $info\n"
    "     */\n"
    "    public static function causedByErrorInfo(array $info): bool\n"
    "    {\n"
    "        return self::matches((string) ($info[2] ?? ''), (string) ($info[0] ?? ''), (int) ($info[1] ?? 0));\n"
    "    }\n"
    "\n"
    "    private static function matches(string $message, string $state, int $driverError): bool\n"
    "    {\n"
    "        if (preg_match('/^SQLSTATE\\[([A-Z0-9]{5})\\]/i', $message, $matches)) {\n"
    "            $state = strtoupper($matches[1]);\n"
    "            if ($driverError === 0 && preg_match('/^SQLSTATE\\[[^]]+\\](?: \\[(\\d+)\\]|: [^:]+: (\\d+)\\b)/', $message, $codes)) {\n"
    "                $driverError = (int) ($codes[1] !== '' ? $codes[1] : $codes[2]);\n"
    "            }\n"
    "        }\n"
    "        $state = strtoupper($state);\n"
    "        // Authentication, constraint and SQL errors are not transport failures, even when their text quotes one.\n"
    "        if (in_array($driverError, [1044, 1045], true) || stripos($message, 'access denied for user') !== false) {\n"
    "            return false;\n"
    "        }\n"
    "        if (str_starts_with($state, '08')) {\n"
    "            return true;\n"
    "        }\n"
    "        if ($state !== '' && $state !== 'HY000') {\n"
    "            return false;\n"
    "        }\n"
    "        if (in_array($driverError, self::DRIVER_ERRORS, true)) {\n"
    "            return true;\n"
    "        }\n"
    "        // PostgreSQL uses driver code 7 for several transport diagnostics; other explicit error numbers win.\n"
    "        if ($driverError !== 0 && $driverError !== 7) {\n"
    "            return false;\n"
    "        }\n"
    "        foreach (self::ERROR_MESSAGES as $needle) {\n"
    "            if (stripos($message, $needle) !== false) {\n"
    "                return true;\n"
    "            }\n"
    "        }\n"
    "        return (bool) preg_match('/^(?:broken pipe|connection lost|connection reset by peer|ssl: (?:handshake|operation|connection) timed out)$/i', trim($message))\n"
    "            || (bool) preg_match('/^PDO::\\w+\\(\\): Send of \\d+ bytes failed with errno=(?:32|54|104|110)\\b/i', $message)\n"
    "            || (bool) preg_match('/\\bORA-0311[34]\\b/i', $message);\n"
    "    }\n"
    "}\n";

static const char* swoole_library_source_core_database_pdo_config =
    "\n"
    "/**\n"
    " * This file is part of Swoole.\n"
    " *\n"
    " * @link     https://www.swoole.com\n"
    " * @contact  team@swoole.com\n"
    " * @license  https://github.com/swoole/library/blob/master/LICENSE\n"
    " */\n"
    "\n"
    "declare(strict_types=1);\n"
    "\n"
    "namespace Swoole\\Database;\n"
    "\n"
    "class PDOConfig\n"
    "{\n"
    "    public const DRIVER_MYSQL = 'mysql';\n"
    "\n"
    "    protected string $driver = self::DRIVER_MYSQL;\n"
    "\n"
    "    protected string $host = '127.0.0.1';\n"
    "\n"
    "    protected int $port = 3306;\n"
    "\n"
    "    protected ?string $unixSocket = null;\n"
    "\n"
    "    protected string $dbname = 'test';\n"
    "\n"
    "    protected string $charset = 'utf8mb4';\n"
    "\n"
    "    protected string $username = 'root';\n"
    "\n"
    "    protected string $password = 'root';\n"
    "\n"
    "    protected array $options = [];\n"
    "\n"
    "    protected bool $retryOnLostConnection = false;\n"
    "\n"
    "    public function getRetryOnLostConnection(): bool\n"
    "    {\n"
    "        return $this->retryOnLostConnection;\n"
    "    }\n"
    "\n"
    "    /** Only enable for work that can safely be repeated after an ambiguous transport failure. */\n"
    "    public function withRetryOnLostConnection(bool $retry): self\n"
    "    {\n"
    "        $this->retryOnLostConnection = $retry;\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    public function getDriver(): string\n"
    "    {\n"
    "        return $this->driver;\n"
    "    }\n"
    "\n"
    "    public function withDriver(string $driver): self\n"
    "    {\n"
    "        $this->driver = $driver;\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    public function getHost(): string\n"
    "    {\n"
    "        return $this->host;\n"
    "    }\n"
    "\n"
    "    public function withHost(string $host): self\n"
    "    {\n"
    "        $this->host = $host;\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    public function getPort(): int\n"
    "    {\n"
    "        return $this->port;\n"
    "    }\n"
    "\n"
    "    public function hasUnixSocket(): bool\n"
    "    {\n"
    "        return $this->unixSocket !== null && $this->unixSocket !== '';\n"
    "    }\n"
    "\n"
    "    public function getUnixSocket(): ?string\n"
    "    {\n"
    "        return $this->unixSocket;\n"
    "    }\n"
    "\n"
    "    public function withUnixSocket(?string $unixSocket): self\n"
    "    {\n"
    "        $this->unixSocket = $unixSocket;\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    public function withPort(int $port): self\n"
    "    {\n"
    "        $this->port = $port;\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    public function getDbname(): string\n"
    "    {\n"
    "        return $this->dbname;\n"
    "    }\n"
    "\n"
    "    public function withDbname(string $dbname): self\n"
    "    {\n"
    "        $this->dbname = $dbname;\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    public function getCharset(): string\n"
    "    {\n"
    "        return $this->charset;\n"
    "    }\n"
    "\n"
    "    public function withCharset(string $charset): self\n"
    "    {\n"
    "        $this->charset = $charset;\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    public function getUsername(): string\n"
    "    {\n"
    "        return $this->username;\n"
    "    }\n"
    "\n"
    "    public function withUsername(string $username): self\n"
    "    {\n"
    "        $this->username = $username;\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    public function getPassword(): string\n"
    "    {\n"
    "        return $this->password;\n"
    "    }\n"
    "\n"
    "    public function withPassword(string $password): self\n"
    "    {\n"
    "        $this->password = $password;\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    public function getOptions(): array\n"
    "    {\n"
    "        return $this->options;\n"
    "    }\n"
    "\n"
    "    public function withOptions(array $options): self\n"
    "    {\n"
    "        $this->options = $options;\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Returns the list of available drivers\n"
    "     *\n"
    "     * @return string[]\n"
    "     */\n"
    "    public static function getAvailableDrivers(): array\n"
    "    {\n"
    "        return [\n"
    "            self::DRIVER_MYSQL,\n"
    "        ];\n"
    "    }\n"
    "}\n";

static const char* swoole_library_source_core_database_pdo_pool =
    "\n"
    "/**\n"
    " * This file is part of Swoole.\n"
    " *\n"
    " * @link     https://www.swoole.com\n"
    " * @contact  team@swoole.com\n"
    " * @license  https://github.com/swoole/library/blob/master/LICENSE\n"
    " */\n"
    "\n"
    "declare(strict_types=1);\n"
    "\n"
    "namespace Swoole\\Database;\n"
    "\n"
    "use Swoole\\ConnectionPool;\n"
    "\n"
    "class PDOPool extends ConnectionPool\n"
    "{\n"
    "    public function __construct(protected PDOConfig $config, int $size = self::DEFAULT_SIZE)\n"
    "    {\n"
    "        parent::__construct(function () {\n"
    "            $driver = $this->config->getDriver();\n"
    "            if ($driver === 'sqlite') {\n"
    "                return new \\PDO($this->createDSN('sqlite'));\n"
    "            }\n"
    "\n"
    "            return new \\PDO($this->createDSN($driver), $this->config->getUsername(), $this->config->getPassword(), $this->config->getOptions());\n"
    "        }, $size, PDOProxy::class);\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Get a PDO connection from the pool. The PDO connection (a PDO object) is wrapped in a PDOProxy object returned.\n"
    "     *\n"
    "     * @param float $timeout the number of seconds to wait for a connection; 0 or less waits with no time limit\n"
    "     * @return PDOProxy|false Returns a PDOProxy object from the pool, or false if no connection is available before the timeout.\n"
    "     *                        {@inheritDoc}\n"
    "     */\n"
    "    public function get(float $timeout = -1)\n"
    "    {\n"
    "        /* @var \\Swoole\\Database\\PDOProxy|false $pdo */\n"
    "        $pdo = parent::get($timeout);\n"
    "        if ($pdo === false) {\n"
    "            return false;\n"
    "        }\n"
    "\n"
    "        $pdo->reset();\n"
    "        $pdo->setRetryOnLostConnection($this->config->getRetryOnLostConnection());\n"
    "\n"
    "        return $pdo;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Return a connection to the pool.\n"
    "     *\n"
    "     * A transaction left open on the connection is rolled back first, so that the next borrower does not work\n"
    "     * inside a transaction it never began. On MySQL and Oracle, autocommit is set back to the value of the pool's\n"
    "     * options, on by default. A connection that cannot be cleaned is replaced; when the replacement cannot be made,\n"
    "     * it is left to the next get() to make it and to report the failure.\n"
    "     *\n"
    "     * The transaction is the one the driver reports. pdo_mysql and pdo_pgsql report a transaction started by\n"
    "     * hand, e.g. with exec('BEGIN'), too, and so does pdo_sqlite as of PHP 8.4 or with Swoole's coroutine SQLite.\n"
    "     * The other drivers only report one started with beginTransaction().\n"
    "     *\n"
    "     * @param PDOProxy|null $connection the connection to return, or null to have a broken connection replaced\n"
    "     */\n"
    "    public function put(mixed $connection): void\n"
    "    {\n"
    "        if ($connection !== null && $this->pool !== null) {\n"
    "            $this->assertCanReturn($connection);\n"
    "        }\n"
    "        if ($this->pool !== null && $connection instanceof PDOProxy && !$this->clean($connection)) {\n"
    "            try {\n"
    "                parent::discard($connection);\n"
    "            } catch (\\Throwable) {\n"
    "                // Putting a connection back is no place to report that a new one cannot be made.\n"
    "            }\n"
    "            return;\n"
    "        }\n"
    "\n"
    "        parent::put($connection);\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Rolls back the transaction left open on the connection, if any, and sets autocommit back.\n"
    "     *\n"
    "     * @return bool false when that fails, as when the connection was lost inside the transaction\n"
    "     */\n"
    "    private function clean(PDOProxy $connection): bool\n"
    "    {\n"
    "        if ($connection->isLost()) {\n"
    "            return false;\n"
    "        }\n"
    "        $pdo = $connection->__getObject();\n"
    "        // The state PDO reports now, not the one the proxy recorded: a connection that was lost reads as inside a\n"
    "        // transaction, the rollback fails, and the connection is replaced.\n"
    "        if ($pdo->inTransaction()) {\n"
    "            try {\n"
    "                if (!$pdo->rollBack()) {\n"
    "                    return false;\n"
    "                }\n"
    "            } catch (\\PDOException) {\n"
    "                return false;\n"
    "            }\n"
    "        }\n"
    "        // pdo_oci reports a transaction only after beginTransaction(). Work done with autocommit off is not seen, and\n"
    "        // would be committed by the first statement of the next borrower, once autocommit is on again.\n"
    "        if ($this->config->getDriver() === 'oci') {\n"
    "            try {\n"
    "                if (!$pdo->getAttribute(\\PDO::ATTR_AUTOCOMMIT) && $pdo->exec('ROLLBACK') === false) {\n"
    "                    return false;\n"
    "                }\n"
    "            } catch (\\PDOException) {\n"
    "                return false;\n"
    "            }\n"
    "        }\n"
    "        // Autocommit turned off on the connection, e.g. with setAttribute(PDO::ATTR_AUTOCOMMIT, false), would leave\n"
    "        // the next borrower inside a transaction from its first statement on. Through the proxy, so that a reconnect\n"
    "        // restores the same value.\n"
    "        if (in_array($this->config->getDriver(), ['mysql', 'oci'], true)) {\n"
    "            $autocommit = (bool) ($this->config->getOptions()[\\PDO::ATTR_AUTOCOMMIT] ?? true);\n"
    "            try {\n"
    "                if ((bool) $pdo->getAttribute(\\PDO::ATTR_AUTOCOMMIT) !== $autocommit && !$connection->setAttribute(\\PDO::ATTR_AUTOCOMMIT, $autocommit)) {\n"
    "                    return false;\n"
    "                }\n"
    "            } catch (\\PDOException) {\n"
    "                return false;\n"
    "            }\n"
    "        }\n"
    "        $connection->reset();\n"
    "\n"
    "        return true;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @purpose create DSN\n"
    "     * @throws \\Exception\n"
    "     */\n"
    "    private function createDSN(string $driver): string\n"
    "    {\n"
    "        if (in_array($driver, ['mysql', 'pgsql', 'oci'], true)) {\n"
    "            foreach (['host' => $this->config->getHost(), 'dbname' => $this->config->getDbname(), 'charset' => $this->config->getCharset(), 'unixSocket' => $this->config->getUnixSocket()] as $name => $value) {\n"
    "                if ($value !== null && (str_contains($value, ';') || str_contains($value, \"\\0\"))) {\n"
    "                    throw new \\InvalidArgumentException(\"Invalid DSN component: {$name}\");\n"
    "                }\n"
    "            }\n"
    "        }\n"
    "        switch ($driver) {\n"
    "            case 'mysql':\n"
    "                if ($this->config->hasUnixSocket()) {\n"
    "                    $dsn = \"mysql:unix_socket={$this->config->getUnixSocket()};dbname={$this->config->getDbname()};charset={$this->config->getCharset()}\";\n"
    "                } else {\n"
    "                    $dsn = \"mysql:host={$this->config->getHost()};port={$this->config->getPort()};dbname={$this->config->getDbname()};charset={$this->config->getCharset()}\";\n"
    "                }\n"
    "                break;\n"
    "            case 'pgsql':\n"
    "                $quote = static fn (string $value): string => \"'\" . str_replace(['\\\\', \"'\"], ['\\\\\\\\', \"\\\\'\"], $value) . \"'\";\n"
    "                $host  = $this->config->hasUnixSocket() ? $this->config->getUnixSocket() : $this->config->getHost();\n"
    "                $dsn   = 'pgsql:host=' . $quote($host) . \";port={$this->config->getPort()};dbname=\" . $quote($this->config->getDbname());\n"
    "                break;\n"
    "            case 'oci':\n"
    "                $host = $this->config->hasUnixSocket() ? $this->config->getUnixSocket() : $this->config->getHost();\n"
    "                if (filter_var($host, FILTER_VALIDATE_IP, FILTER_FLAG_IPV6)) {\n"
    "                    $host = '[' . $host . ']';\n"
    "                } elseif (!preg_match('/^(?:[a-z0-9_.-]+|\\[[a-f0-9:.%_-]+\\])$/iD', $host)) {\n"
    "                    throw new \\InvalidArgumentException('Invalid Oracle DSN host');\n"
    "                }\n"
    "                if (!preg_match('/^[a-z0-9_.$-]+$/iD', $this->config->getDbname()) || !preg_match('/^[a-z0-9_]+$/iD', $this->config->getCharset())) {\n"
    "                    throw new \\InvalidArgumentException('Invalid Oracle DSN service or charset');\n"
    "                }\n"
    "                $dsn = 'oci:dbname=' . $host . ':' . $this->config->getPort() . '/' . $this->config->getDbname() . ';charset=' . $this->config->getCharset();\n"
    "                break;\n"
    "            case 'sqlite':\n"
    "                // There are three types of SQLite databases: databases on disk, databases in memory, and temporary\n"
    "                // databases (which are deleted when the connections are closed). It doesn't make sense to use\n"
    "                // connection pool for the latter two types of databases, because each connection connects to a\n"
    "                //different in-memory or temporary SQLite database.\n"
    "                if ($this->config->getDbname() === '') {\n"
    "                    throw new \\Exception('Connection pool in Swoole does not support temporary SQLite databases.');\n"
    "                }\n"
    "                if ($this->config->getDbname() === ':memory:') {\n"
    "                    throw new \\Exception('Connection pool in Swoole does not support creating SQLite databases in memory.');\n"
    "                }\n"
    "                $dsn = 'sqlite:' . $this->config->getDbname();\n"
    "                break;\n"
    "            default:\n"
    "                throw new \\Exception('Unsupported Database Driver:' . $driver);\n"
    "        }\n"
    "        return $dsn;\n"
    "    }\n"
    "}\n";

static const char* swoole_library_source_core_database_pdo_proxy =
    "\n"
    "/**\n"
    " * This file is part of Swoole.\n"
    " *\n"
    " * @link     https://www.swoole.com\n"
    " * @contact  team@swoole.com\n"
    " * @license  https://github.com/swoole/library/blob/master/LICENSE\n"
    " */\n"
    "\n"
    "declare(strict_types=1);\n"
    "\n"
    "namespace Swoole\\Database;\n"
    "\n"
    "/**\n"
    " * A lost connection is reported without replaying an ambiguous call. A later explicit call reconnects.\n"
    " * setRetryOnLostConnection(true) opts in to replay outside transactions; only use it for repeatable work.\n"
    " * Pools restore the policy from PDOConfig::withRetryOnLostConnection() on every checkout.\n"
    " *\n"
    " * @method \\PDO __getObject()\n"
    " */\n"
    "class PDOProxy extends ObjectProxy\n"
    "{\n"
    "    /** @var \\PDO */\n"
    "    protected $__object;\n"
    "\n"
    "    protected array $setAttributeContext = [];\n"
    "\n"
    "    /** @var callable */\n"
    "    protected $constructor;\n"
    "\n"
    "    protected int $round = 0;\n"
    "\n"
    "    protected bool $retryOnLostConnection = false;\n"
    "\n"
    "    /**\n"
    "     * Whether the connection is inside a transaction, as PDO reported it right after the last call that reached the\n"
    "     * server and could start or end one: exec(), query(), beginTransaction(), commit() and rollBack() of the proxy,\n"
    "     * and execute() of its statements. It is what inTransaction() reports, and it decides whether a call that runs\n"
    "     * into a lost connection may reconnect.\n"
    "     *\n"
    "     * PDO is not asked before the call: on PostgreSQL a connection found dead by any call, a destructor included,\n"
    "     * is reported as inside a transaction from then on, which says nothing about the transaction before it died.\n"
    "     */\n"
    "    protected bool $openTransaction = false;\n"
    "\n"
    "    /**\n"
    "     * Whether the connection was lost and not replaced yet: a lost connection reported inside a transaction, which\n"
    "     * is not retried, or a reconnect that failed. PDO keeps reporting such a connection as inside a transaction, so\n"
    "     * the state PDO reports cannot tell it; the next call reconnects first.\n"
    "     */\n"
    "    protected bool $lost = false;\n"
    "\n"
    "    public function __construct(callable $constructor)\n"
    "    {\n"
    "        parent::__construct($constructor());\n"
    "        $this->__object->setAttribute(\\PDO::ATTR_ERRMODE, \\PDO::ERRMODE_EXCEPTION);\n"
    "        $this->constructor = $constructor;\n"
    "    }\n"
    "\n"
    "    public function __call(string $name, array $arguments)\n"
    "    {\n"
    "        if ($this->lost) {\n"
    "            if (in_array(strtolower($name), ['errorinfo', 'errorcode'], true)) {\n"
    "                // Diagnostics belong to the failed call, so reading them must not reconnect and clear them.\n"
    "                return $this->__object->{$name}(...$arguments);\n"
    "            }\n"
    "            if (strcasecmp($name, 'rollBack') === 0) {\n"
    "                // The transaction died with the connection, and the server has rolled it back. Nothing to send.\n"
    "                return true;\n"
    "            }\n"
    "            $this->reconnect();\n"
    "        }\n"
    "\n"
    "        // The calls that can start or end a transaction, by hand as well: exec('BEGIN') and query('COMMIT') included.\n"
    "        $changesTransaction = in_array(strtolower($name), ['exec', 'query', 'begintransaction', 'commit', 'rollback'], true);\n"
    "        try {\n"
    "            $ret = $this->__object->{$name}(...$arguments);\n"
    "        } catch (\\PDOException $e) {\n"
    "            if (!DetectsLostConnections::causedByLostConnection($e)) {\n"
    "                if ($changesTransaction) {\n"
    "                    // The server answered, so the state PDO reports is the real one.\n"
    "                    $this->openTransaction = $this->__object->inTransaction();\n"
    "                }\n"
    "                throw $e;\n"
    "            }\n"
    "            if ($this->openTransaction || !$this->retryOnLostConnection) {\n"
    "                // The transaction died with the connection. The caller is told, and the next call reconnects.\n"
    "                $this->markAsLost();\n"
    "                throw $e;\n"
    "            }\n"
    "            $this->reconnect();\n"
    "            $ret = $this->__object->{$name}(...$arguments);\n"
    "        }\n"
    "        // ERRMODE_SILENT and ERRMODE_WARNING report a lost connection as false plus errorInfo(), not as an exception.\n"
    "        // A false that is a lost connection is retried the same way; any other false is the caller's error.\n"
    "        if ($ret === false && !$this->lost && self::errorInfoIsLostConnection($this->__object->errorInfo())) {\n"
    "            if ($this->openTransaction || !$this->retryOnLostConnection) {\n"
    "                $this->markAsLost();\n"
    "                return false;\n"
    "            }\n"
    "            $this->reconnect();\n"
    "            $ret = $this->__object->{$name}(...$arguments);\n"
    "        }\n"
    "        if ($changesTransaction) {\n"
    "            $this->openTransaction = $this->__object->inTransaction();\n"
    "        }\n"
    "\n"
    "        // Not a statement but false when the call failed and the error mode is not the exception one.\n"
    "        if ($ret instanceof \\PDOStatement && (strcasecmp($name, 'prepare') === 0 || strcasecmp($name, 'query') === 0)) {\n"
    "            $ret = new PDOStatementProxy($ret, $this);\n"
    "        }\n"
    "\n"
    "        return $ret;\n"
    "    }\n"
    "\n"
    "    /** Opt in only when repeating the operation cannot duplicate effects. */\n"
    "    public function setRetryOnLostConnection(bool $retry): void\n"
    "    {\n"
    "        $this->retryOnLostConnection = $retry;\n"
    "    }\n"
    "\n"
    "    public function shouldRetryOnLostConnection(): bool\n"
    "    {\n"
    "        return $this->retryOnLostConnection;\n"
    "    }\n"
    "\n"
    "    public function getRound(): int\n"
    "    {\n"
    "        return $this->round;\n"
    "    }\n"
    "\n"
    "    public function reconnect(): void\n"
    "    {\n"
    "        // Stays set when the constructor throws, e.g. while the server restarts: the next call tries again.\n"
    "        $this->lost = true;\n"
    "        parent::__construct(($this->constructor)());\n"
    "        $this->lost            = false;\n"
    "        $this->openTransaction = false;\n"
    "        $this->__object->setAttribute(\\PDO::ATTR_ERRMODE, \\PDO::ERRMODE_EXCEPTION);\n"
    "        $this->round++;\n"
    "        /* restore context */\n"
    "        foreach ($this->setAttributeContext as $attribute => $value) {\n"
    "            $this->__object->setAttribute($attribute, $value);\n"
    "        }\n"
    "    }\n"
    "\n"
    "    public function setAttribute(int $attribute, mixed $value): bool\n"
    "    {\n"
    "        $this->setAttributeContext[$attribute] = $value;\n"
    "        return $this->__object->setAttribute($attribute, $value);\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Whether the connection is inside a transaction: one begun with beginTransaction() or by hand, e.g. with\n"
    "     * exec('BEGIN'), and not ended, by commit() or rollBack(), by exec('COMMIT'), or by a statement that commits\n"
    "     * implicitly. It is the state PDO reported after the last call that could start or end a transaction, and false\n"
    "     * for a connection known to be lost, whose transaction went down with it.\n"
    "     */\n"
    "    public function inTransaction(): bool\n"
    "    {\n"
    "        return $this->openTransaction;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Forgets the transaction state the proxy recorded: when the pool hands the connection out, or after it rolled the\n"
    "     * transaction back on the PDO object.\n"
    "     */\n"
    "    public function reset(): void\n"
    "    {\n"
    "        $this->openTransaction = false;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * The same as inTransaction(), which the statements of the proxy call.\n"
    "     *\n"
    "     * @internal\n"
    "     */\n"
    "    public function hasOpenTransaction(): bool\n"
    "    {\n"
    "        return $this->openTransaction;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Records the transaction state PDO reports now. Called by a statement of the proxy after a call that reached the\n"
    "     * server and could start or end a transaction, e.g. prepare('BEGIN')->execute().\n"
    "     *\n"
    "     * @internal\n"
    "     */\n"
    "    public function recordTransactionState(): void\n"
    "    {\n"
    "        if (!$this->lost) {\n"
    "            $this->openTransaction = $this->__object->inTransaction();\n"
    "        }\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Whether the connection was lost and not replaced yet; the next call reconnects first.\n"
    "     *\n"
    "     * @internal\n"
    "     */\n"
    "    public function isLost(): bool\n"
    "    {\n"
    "        return $this->lost;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Records that the connection was lost inside a transaction, which went down with it: the next call reconnects\n"
    "     * first. Called by the proxy, and by a statement of the connection that reports a lost connection.\n"
    "     *\n"
    "     * @internal\n"
    "     */\n"
    "    public function markAsLost(): void\n"
    "    {\n"
    "        $this->lost            = true;\n"
    "        $this->openTransaction = false;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @param array{0?: string, 1?: int|string|null, 2?: string|null}|array $info PDO::errorInfo()\n"
    "     */\n"
    "    private static function errorInfoIsLostConnection(array $info): bool\n"
    "    {\n"
    "        return DetectsLostConnections::causedByErrorInfo($info);\n"
    "    }\n"
    "}\n";

static const char* swoole_library_source_core_database_pdo_statement_proxy =
    "\n"
    "/**\n"
    " * This file is part of Swoole.\n"
    " *\n"
    " * @link     https://www.swoole.com\n"
    " * @contact  team@swoole.com\n"
    " * @license  https://github.com/swoole/library/blob/master/LICENSE\n"
    " */\n"
    "\n"
    "declare(strict_types=1);\n"
    "\n"
    "namespace Swoole\\Database;\n"
    "\n"
    "/**\n"
    " * The proxy class for PHP class PDOStatement.\n"
    " *\n"
    " * @see https://www.php.net/PDOStatement The PDOStatement class\n"
    " */\n"
    "class PDOStatementProxy extends ObjectProxy\n"
    "{\n"
    "    /** @var \\PDOStatement */\n"
    "    protected $__object;\n"
    "\n"
    "    protected array $setAttributeContext = [];\n"
    "\n"
    "    protected array $setFetchModeContext = [];\n"
    "\n"
    "    protected array $bindParamContext = [];\n"
    "\n"
    "    protected array $bindColumnContext = [];\n"
    "\n"
    "    protected array $bindValueContext = [];\n"
    "\n"
    "    /** @var int */\n"
    "    protected $parentRound;\n"
    "\n"
    "    public function __construct(\\PDOStatement $object, protected PDOProxy $parent)\n"
    "    {\n"
    "        parent::__construct($object);\n"
    "        $this->parentRound = $parent->getRound();\n"
    "    }\n"
    "\n"
    "    public function __call(string $name, array $arguments)\n"
    "    {\n"
    "        // Not the state PDO reports now, which a connection found dead makes \"inside a transaction\" on PostgreSQL, but\n"
    "        // the one the parent recorded, which includes a transaction started by hand. A connection known to be lost is\n"
    "        // in no transaction any more: that one went down with it, and was reported.\n"
    "        if (strcasecmp($name, 'execute') === 0 && ($this->parent->isLost() || $this->parent->getRound() !== $this->parentRound)) {\n"
    "            if (!$this->reprepare()) {\n"
    "                return false;\n"
    "            }\n"
    "        }\n"
    "        $inTransaction = $this->parent->hasOpenTransaction();\n"
    "        $failed        = null;\n"
    "        try {\n"
    "            $ret = $this->__object->{$name}(...$arguments);\n"
    "        } catch (\\PDOException $e) {\n"
    "            $failed = $e;\n"
    "            $ret    = false;\n"
    "        }\n"
    "        $lost = $failed !== null\n"
    "            ? DetectsLostConnections::causedByLostConnection($failed)\n"
    "            : ($ret === false && self::errorInfoIsLostConnection($this->__object->errorInfo(), $this->parent->__getObject()->errorInfo()));\n"
    "        if ($ret === false && $lost) {\n"
    "            if ($inTransaction || !$this->parent->shouldRetryOnLostConnection()) {\n"
    "                // The transaction died with the connection. The caller is told, and the next call reconnects.\n"
    "                if ($this->parent->getRound() === $this->parentRound) {\n"
    "                    $this->parent->markAsLost();\n"
    "                }\n"
    "                if ($failed !== null) {\n"
    "                    throw $failed;\n"
    "                }\n"
    "                return false;\n"
    "            }\n"
    "            // Only execute() is retried on a fresh connection, since it runs the statement from the start. The\n"
    "            // other methods (fetch*(), rowCount(), ...) read the result of an execute() that went down with the\n"
    "            // connection; re-preparing the statement and calling one of them on it without executing it first\n"
    "            // returns no rows and no error, so a lost connection there surfaces as the failure it is.\n"
    "            if (strcasecmp($name, 'execute') !== 0) {\n"
    "                if ($failed !== null) {\n"
    "                    throw $failed;\n"
    "                }\n"
    "                return false;\n"
    "            }\n"
    "            $ret = $this->reexecute($arguments);\n"
    "            if ($ret === false && $failed !== null) {\n"
    "                throw $failed;\n"
    "            }\n"
    "        } elseif ($failed !== null) {\n"
    "            throw $failed;\n"
    "        }\n"
    "\n"
    "        // The statement may have started or ended a transaction, e.g. prepare('BEGIN') or a statement that commits\n"
    "        // implicitly. Recorded on the parent, unless the parent is on another connection by now.\n"
    "        if (strcasecmp($name, 'execute') === 0 && $this->parent->getRound() === $this->parentRound) {\n"
    "            $this->parent->recordTransactionState();\n"
    "        }\n"
    "\n"
    "        return $ret;\n"
    "    }\n"
    "\n"
    "    public function setAttribute(int $attribute, mixed $value): bool\n"
    "    {\n"
    "        $this->setAttributeContext[$attribute] = $value;\n"
    "        return $this->__object->setAttribute($attribute, $value);\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Set the default fetch mode for this statement.\n"
    "     *\n"
    "     * @see https://www.php.net/manual/en/pdostatement.setfetchmode.php\n"
    "     */\n"
    "    public function setFetchMode(int $mode, mixed ...$args): bool\n"
    "    {\n"
    "        $this->setFetchModeContext = func_get_args();\n"
    "        return $this->__object->setFetchMode(...$this->setFetchModeContext);\n"
    "    }\n"
    "\n"
    "    public function bindParam(int|string $param, mixed &$var, int $type = \\PDO::PARAM_STR, int $maxLength = 0, mixed $driverOptions = null): bool\n"
    "    {\n"
    "        // The variable is kept by reference: a statement prepared again after a reconnect is bound to the variable of\n"
    "        // the caller, as the first one was, and not to the value the variable had at the time of this call.\n"
    "        $key = self::parameterKey($param);\n"
    "        unset($this->bindValueContext[$key]);\n"
    "        $this->bindParamContext[$key] = [&$var, $type, $maxLength, $driverOptions];\n"
    "        return $this->__object->bindParam($param, $var, $type, $maxLength, $driverOptions);\n"
    "    }\n"
    "\n"
    "    public function bindColumn(int|string $column, mixed &$var, int $type = \\PDO::PARAM_STR, int $maxLength = 0, mixed $driverOptions = null): bool\n"
    "    {\n"
    "        $this->bindColumnContext[$column] = [&$var, $type, $maxLength, $driverOptions];\n"
    "        return $this->__object->bindColumn($column, $var, $type, $maxLength, $driverOptions);\n"
    "    }\n"
    "\n"
    "    public function bindValue(int|string $param, mixed $value, int $type = \\PDO::PARAM_STR): bool\n"
    "    {\n"
    "        $key = self::parameterKey($param);\n"
    "        unset($this->bindParamContext[$key]);\n"
    "        $this->bindValueContext[$key] = [$value, $type];\n"
    "        return $this->__object->bindValue($param, $value, $type);\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Prepare the statement again on the current connection and run execute() with the original arguments.\n"
    "     *\n"
    "     * @param array<int|string, mixed> $arguments\n"
    "     */\n"
    "    private function reexecute(array $arguments): mixed\n"
    "    {\n"
    "        return $this->reprepare() && $this->__object->execute(...$arguments);\n"
    "    }\n"
    "\n"
    "    private function reprepare(): bool\n"
    "    {\n"
    "        // A parent of another round has reconnected already, unless that reconnect failed and left it lost.\n"
    "        if ($this->parent->getRound() === $this->parentRound || $this->parent->isLost()) {\n"
    "            $this->parent->reconnect();\n"
    "        }\n"
    "        // Record the parent's round, or the next lost connection on this statement looks like one the parent\n"
    "        // has already recovered from, and the statement is prepared again on the dead connection instead.\n"
    "        $this->parentRound = $this->parent->getRound();\n"
    "        $statement         = $this->parent->__getObject()->prepare($this->__object->queryString);\n"
    "        if ($statement === false) {\n"
    "            return false;\n"
    "        }\n"
    "        $this->__object = $statement;\n"
    "\n"
    "        foreach ($this->setAttributeContext as $attribute => $value) {\n"
    "            $this->__object->setAttribute($attribute, $value);\n"
    "        }\n"
    "        if (!empty($this->setFetchModeContext)) {\n"
    "            $this->__object->setFetchMode(...$this->setFetchModeContext);\n"
    "        }\n"
    "        foreach ($this->bindParamContext as $param => $item) {\n"
    "            $this->__object->bindParam($param, ...$item);\n"
    "        }\n"
    "        foreach ($this->bindColumnContext as $column => $item) {\n"
    "            $this->__object->bindColumn($column, ...$item);\n"
    "        }\n"
    "        foreach ($this->bindValueContext as $parameter => $item) {\n"
    "            $this->__object->bindValue($parameter, ...$item);\n"
    "        }\n"
    "\n"
    "        return true;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @param array{0?: string, 1?: int|string|null, 2?: string|null} $statementInfo\n"
    "     * @param array{0?: string, 1?: int|string|null, 2?: string|null} $connectionInfo\n"
    "     */\n"
    "    private static function errorInfoIsLostConnection(array $statementInfo, array $connectionInfo): bool\n"
    "    {\n"
    "        foreach ([$statementInfo, $connectionInfo] as $info) {\n"
    "            if (DetectsLostConnections::causedByErrorInfo($info)) {\n"
    "                return true;\n"
    "            }\n"
    "        }\n"
    "\n"
    "        return false;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * The key a parameter is recorded under. A parameter is bound by bindParam() or by bindValue(), whichever was\n"
    "     * called last, and is recorded once: the bindings are made again by kind after a reconnect, not in the order of\n"
    "     * the calls. PDO takes a name with or without its leading colon.\n"
    "     */\n"
    "    private static function parameterKey(int|string $param): int|string\n"
    "    {\n"
    "        return is_string($param) && !str_starts_with($param, ':') ? ':' . $param : $param;\n"
    "    }\n"
    "}\n";

static const char* swoole_library_source_core_database_redis_config =
    "\n"
    "/**\n"
    " * This file is part of Swoole.\n"
    " *\n"
    " * @link     https://www.swoole.com\n"
    " * @contact  team@swoole.com\n"
    " * @license  https://github.com/swoole/library/blob/master/LICENSE\n"
    " */\n"
    "\n"
    "declare(strict_types=1);\n"
    "\n"
    "namespace Swoole\\Database;\n"
    "\n"
    "class RedisConfig\n"
    "{\n"
    "    protected string $host = '127.0.0.1';\n"
    "\n"
    "    protected int $port = 6379;\n"
    "\n"
    "    protected float $timeout = 0.0;\n"
    "\n"
    "    protected string $reserved = '';\n"
    "\n"
    "    protected int $retry_interval = 0;\n"
    "\n"
    "    protected float $read_timeout = 0.0;\n"
    "\n"
    "    /** @var string|string[] */\n"
    "    protected string|array $auth = '';\n"
    "\n"
    "    protected int $dbIndex = 0;\n"
    "\n"
    "    /**\n"
    "     * @var array<int, mixed>\n"
    "     */\n"
    "    protected array $options = [];\n"
    "\n"
    "    public function getHost(): string\n"
    "    {\n"
    "        return $this->host;\n"
    "    }\n"
    "\n"
    "    public function withHost(string $host): self\n"
    "    {\n"
    "        $this->host = $host;\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    public function getPort(): int\n"
    "    {\n"
    "        return $this->port;\n"
    "    }\n"
    "\n"
    "    public function withPort(int $port): self\n"
    "    {\n"
    "        $this->port = $port;\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    public function getTimeout(): float\n"
    "    {\n"
    "        return $this->timeout;\n"
    "    }\n"
    "\n"
    "    public function withTimeout(float $timeout): self\n"
    "    {\n"
    "        $this->timeout = $timeout;\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    public function getReserved(): string\n"
    "    {\n"
    "        return $this->reserved;\n"
    "    }\n"
    "\n"
    "    public function withReserved(string $reserved): self\n"
    "    {\n"
    "        $this->reserved = $reserved;\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    public function getRetryInterval(): int\n"
    "    {\n"
    "        return $this->retry_interval;\n"
    "    }\n"
    "\n"
    "    public function withRetryInterval(int $retry_interval): self\n"
    "    {\n"
    "        $this->retry_interval = $retry_interval;\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    public function getReadTimeout(): float\n"
    "    {\n"
    "        return $this->read_timeout;\n"
    "    }\n"
    "\n"
    "    public function withReadTimeout(float $read_timeout): self\n"
    "    {\n"
    "        $this->read_timeout = $read_timeout;\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @return string|string[]\n"
    "     */\n"
    "    public function getAuth(): string|array\n"
    "    {\n"
    "        return $this->auth;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * @param string|string[] $auth string for password only, array for [username, password]\n"
    "     */\n"
    "    public function withAuth(string|array $auth): self\n"
    "    {\n"
    "        $this->auth = $auth;\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    public function getDbIndex(): int\n"
    "    {\n"
    "        return $this->dbIndex;\n"
    "    }\n"
    "\n"
    "    public function withDbIndex(int $dbIndex): self\n"
    "    {\n"
    "        $this->dbIndex = $dbIndex;\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Add a configurable option.\n"
    "     */\n"
    "    public function withOption(int $option, mixed $value): self\n"
    "    {\n"
    "        $this->options[$option] = $value;\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Add/override configurable options.\n"
    "     *\n"
    "     * @param array<int, mixed> $options\n"
    "     */\n"
    "    public function setOptions(array $options): self\n"
    "    {\n"
    "        $this->options = $options;\n"
    "        return $this;\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Get configurable options.\n"
    "     *\n"
    "     * @return array<int, mixed>\n"
    "     */\n"
    "    public function getOptions(): array\n"
    "    {\n"
    "        return $this->options;\n"
    "    }\n"
    "}\n";

static const char* swoole_library_source_core_database_redis_pool =
    "\n"
    "/**\n"
    " * This file is part of Swoole.\n"
    " *\n"
    " * @link     https://www.swoole.com\n"
    " * @contact  team@swoole.com\n"
    " * @license  https://github.com/swoole/library/blob/master/LICENSE\n"
    " */\n"
    "\n"
    "declare(strict_types=1);\n"
    "\n"
    "namespace Swoole\\Database;\n"
    "\n"
    "use Redis;\n"
    "use Swoole\\ConnectionPool;\n"
    "\n"
    "/**\n"
    " * @method \\Redis|false get(float $timeout = -1)\n"
    " */\n"
    "class RedisPool extends ConnectionPool\n"
    "{\n"
    "    public function __construct(protected RedisConfig $config, int $size = self::DEFAULT_SIZE)\n"
    "    {\n"
    "        parent::__construct(function () {\n"
    "            $redis = new \\Redis();\n"
    "            // Every argument is passed, in the position phpredis defines for it: leaving one out shifts the ones\n"
    "            // after it into the wrong parameters (a read timeout became the connect timeout, a retry interval\n"
    "            // landed in the persistent id). The zero defaults mean \"unset\" to phpredis, as they do to the config.\n"
    "            $redis->connect(\n"
    "                $this->config->getHost(),\n"
    "                $this->config->getPort(),\n"
    "                $this->config->getTimeout(),\n"
    "                null, // persistent_id: a pooled connection is never persistent\n"
    "                $this->config->getRetryInterval(),\n"
    "                $this->config->getReadTimeout()\n"
    "            );\n"
    "            if ($this->config->getAuth() !== '' && $this->config->getAuth() !== []) {\n"
    "                $redis->auth($this->config->getAuth());\n"
    "            }\n"
    "            if ($this->config->getDbIndex() !== 0) {\n"
    "                $redis->select($this->config->getDbIndex());\n"
    "            }\n"
    "\n"
    "            /* Set Redis options. */\n"
    "            foreach ($this->config->getOptions() as $key => $value) {\n"
    "                $redis->setOption($key, $value);\n"
    "            }\n"
    "\n"
    "            return $redis;\n"
    "        }, $size, null, static function (\\Redis $connection): void {\n"
    "            $connection->close();\n"
    "        });\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Return a connection to the pool.\n"
    "     *\n"
    "     * A connection left in MULTI or pipeline mode, as by a transaction that was never executed, is brought back to\n"
    "     * the normal mode first, so that the commands of the next borrower are run instead of queued. A connection that\n"
    "     * cannot be brought back is replaced; when the replacement cannot be made, it is left to the next get() to make\n"
    "     * it and to report the failure.\n"
    "     *\n"
    "     * WATCH is cleared and the configured database is selected before the next borrower receives the connection.\n"
    "     *\n"
    "     * @param \\Redis|null $connection the connection to return, or null to have a broken connection replaced\n"
    "     */\n"
    "    public function put(mixed $connection): void\n"
    "    {\n"
    "        if ($connection !== null && $this->pool !== null) {\n"
    "            $this->assertCanReturn($connection);\n"
    "        }\n"
    "        if ($this->pool !== null && $connection instanceof \\Redis && !$this->clean($connection)) {\n"
    "            try {\n"
    "                parent::discard($connection);\n"
    "            } catch (\\Throwable) {\n"
    "                // Putting a connection back is no place to report that a new one cannot be made.\n"
    "            }\n"
    "            return;\n"
    "        }\n"
    "\n"
    "        parent::put($connection);\n"
    "    }\n"
    "\n"
    "    /**\n"
    "     * Discards a transaction or a pipeline left open on the connection, if any.\n"
    "     *\n"
    "     * @return bool false when that fails, as when the connection was lost\n"
    "     */\n"
    "    private function clean(\\Redis $connection): bool\n"
    "    {\n"
    "        try {\n"
    "            if (!$connection->isConnected()) {\n"
    "                return false;\n"
    "            }\n"
    "            if ($connection->getMode() !== \\Redis::ATOMIC) {\n"
    "                $connection->discard();\n"
    "            }\n"
    "            return $connection->getMode() === \\Redis::ATOMIC\n"
    "                && $connection->unwatch()\n"
    "                && $connection->select($this->config->getDbIndex());\n"
    "        } catch (\\RedisException) {\n"
    "            return false;\n"
    "        }\n"
    "    }\n"
    "}\n";

